function pb.model(ks,ls,ms)
local ns=tostring(ks)..rcf[2806]..tostring(ms and ms.atk)..rcf[2806]..tostring(ms and ms.cd)
local ps=pb._model[ns]
if ps~=nil then
return ps or nil
end
local qs,rs={},false
local ss=math.max(0.3,tonumber(ms and ms.cd)or 2)
local ts=math.min(1,(tonumber(ls and ls.n)or 1)/4)
