for ys,zs in ipairs(us and type(vs)==rcf[2664]and vs or{})do
if zs.hand then
ws[zs.pid]=true
end
xs[zs.pid]=zs.nums
end
for As,Bs in pairs(pb.rules(ks))do
if not ws[As]then
local Cs={}
for Ds,Es in pairs(type(xs[As])==rcf[2664]and xs[As]or{})do
Cs[Ds]=Es
end
for Fs,Gs in pairs(type(Bs.nums)==rcf[2664]and Bs.nums or{})do
Cs[Fs]=Gs
end
local Hs=Bs.trigger~=nil and tostring(Bs.trigger):find(rcf[3084],1,true)~=nil
if Bs.family==rcf[2866]then
