end
if type(Cs.ampFrom)==rcf[2664]and tostring(Cs.ampFrom.kind)==rcf[2504]and(tonumber(Cs.ampFrom.amp)or 0)>0 then
local Ws=(type(Cs.secsBy)==rcf[2664]and#Cs.secsBy>0)and Cs.secsBy or{tonumber(Cs.secsSeen)or tonumber(Cs.secs)or 5}
qs.flames,rs={amp=tonumber(Cs.ampFrom.amp),secs=Ws},true
end
elseif Bs.family==rcf[2920]then
qs.exec,rs=tonumber(Cs.below)or 0.25,true
