local yeb,zeb,Aeb=ueb.forge_until(reb,seb)
web.sell=ueb.rack_count(reb)+(tonumber(Aeb)or 0)
web.coins=ueb.rack_value(reb)
local Beb=math.max(0,teb-xeb)
if veb.upgrade then
local Ceb
for Deb,Eeb in ipairs({rcf[3746],rcf[3747]})do
