local Heb=Geb and tonumber(Geb.cost)or nil
if Heb and Heb<=Beb and(not Ceb or Heb<Ceb.cost)then
Ceb={kind=Eeb,cost=Heb,to=Feb+1}
end
end
if Ceb then
web.upgrade=Ceb
