if Ffb~=Gfb then
return Ffb<Gfb
end
if ab.DEF_WANT[Dfb.item_id]~=ab.DEF_WANT[Efb.item_id]then
return ab.DEF_WANT[Dfb.item_id]<ab.DEF_WANT[Efb.item_id]
end
return Dfb.g>Efb.g
