if dkb<=0 or(akb or 0)<=0 then
return 0,0
end
local ekb=math.min(akb,dkb)
local fkb=kb.base(_jb)
if fkb<=0 then
return 0,ekb
end
return kb.share(_jb.unit_id)*(kb.score(kb.whatIf(_jb,{xp=bkb+ekb}))/fkb-1)*100,ekb
end
