function kb.relicWorth(gkb,hkb)
local ikb=hkb._unique_item_data and hkb._unique_item_data._unique_relic_data
if not ikb then
return 0
end
local jkb=N.Items[hkb.item_id]or{}
local kkb,lkb=V.types(gkb.unit_id)
if jkb.main_damage_type and jkb.main_damage_type~=rcf[3391]and jkb.main_damage_type~=lkb then
return 0
end
local mkb,nkb=0,0
for okb,pkb in pairs(ikb._core_damage_type_buffs or{})do
if kkb[pkb.damage_type]then
mkb=mkb+(tonumber(pkb.mul)or 0)+(tonumber(pkb.add_upg)or 0)*0.01+(tonumber(pkb.pen)or 0)*0.001
nkb=nkb+(tonumber(pkb.crit)or 0)
end
end
mkb=mkb+nkb*0.5
local qkb=V.rows(gkb.unit_id)
local rkb=qkb and qkb[qkb.max]
local skb=(rkb and tonumber(rkb.cd)or 0)*V.mult(gkb,rcf[3117])
for tkb,vkb in pairs(ikb._unique_relic_effects or{})do
local wkb=type(vkb.params)==rcf[2664]and vkb.params or{}
if vkb.id==rcf[3810]then
local xkb=math.min(1,(tonumber(wkb.extra_damage)or 0)*skb/math.max(1,tonumber(wkb.time_interval)or 40))
local ykb=V.DRONES and V.DRONES[gkb.unit_id]
if ykb and ykb.late and skb>0 then
local zkb=1/skb
xkb=xkb*zkb/(zkb+(tonumber(ykb.max)or 0)*(tonumber(ykb.late.dmg)or 0)*(tonumber(ykb.hits)or 1)/math.max(0.1,tonumber(ykb.late.cd)or 4))
end
mkb=mkb+xkb
elseif vkb.id==rcf[3811]then
mkb=mkb+(tonumber(wkb.dmg_buff)or 0)*0.25
elseif vkb.id==rcf[3812]then
mkb=mkb+(tonumber(wkb.dmg_buff)or 0)*nkb
elseif vkb.id==rcf[3813]then
if kkb.magic then
mkb=0
else
mkb=mkb+(tonumber(wkb.dmg_buff)or 0)*0.3
end
elseif vkb.id==rcf[3814]then
if kkb.water_damage then
mkb=mkb+0.05
end
elseif vkb.id==rcf[2816]then
local Akb=tonumber(wkb.duration_buff)or tonumber(type(vkb.static_params)==rcf[2664]and vkb.static_params.duration_buff)or 2
local Bkb,Ckb=pcall(V.attackInfo,rkb and rkb.atk,rkb and rkb.range)
local Dkb,Ekb=Bkb and tonumber(Ckb.burn)or 0,Bkb and tonumber(Ckb.dot)or 0
if Dkb<=0 then
local Fkb,Gkb=pcall(pb.model,gkb.unit_id,Bkb and Ckb or nil,rkb)
if Fkb and type(Gkb)==rcf[2664]and(tonumber(Gkb.burnDot)or 0)>0 then
Dkb,Ekb=Gkb.burnDot,Ekb+(tonumber(Gkb.dot)or 0)
end
end
mkb=mkb+Dkb*math.max(0,Akb-1)/(1+Ekb)
end
end
return mkb
end
function kb.modShares(Hkb,Ikb)
