Xkb[_kb.id]=alb
local blb,clb=pcall(V.elem,_kb.id,type(Qkb)==rcf[2664]and type(Qkb.weak)==rcf[2664]and{weak=Qkb.weak,strong=Qkb.strong or{},res=Qkb.res}or nil)
Ykb[_kb.id]=blb and tonumber(clb)or 1
