local qob=kb.level(oob)
local rob=qob>kob and string.format(rcf[3829],kob,qob)or string.format(rcf[3830],kob)
cb.add(string.format(rcf[3836],hob,bob.name),hob,rcf[3837],string.format(rcf[3838],U.fmt(pob),rob))
kb.note(string.format(rcf[3839],bob.name,hob,U.fmt(pob),rob,math.abs(pob-gob)>gob*0.1 and string.format(rcf[3840],U.fmt(gob))or rcf[1580]))
