function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==rcf[1580]then
return
end
local Aqb=N.session()
if not(Aqb and Aqb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(rcf[3915],rcf[3904],rcf[3916],rcf[3917])
end
local Bqb
for Cqb,Dqb in ipairs(P.goals or{})do
if Dqb.pinned and Dqb.uuid==O.evolveUnit then
Bqb=Dqb
break
end
end
if not Bqb then
local Eqb=Aqb.collection:get_unit_by_uuid(O.evolveUnit)
local Fqb=N.Units[Eqb.unit_id]
if not(Fqb and Fqb.evolve and Fqb.evolve.evolve_unit)then
ab.pickDone(rcf[3915],rcf[3904],V.name(Eqb.unit_id)..rcf[3918],rcf[3917])
end
return
end
ab.pickNote.autoEvolve=nil
if not Bqb.ready and ab.evolveBuy(Bqb)then
for Gqb,Hqb in ipairs(P.goals or{})do
if Hqb.pinned and Hqb.uuid==O.evolveUnit then
Bqb=Hqb
break
end
end
end
if not Bqb.ready then
return
end
local Iqb={}
for Jqb,Kqb in ipairs(V.equipped())do
Iqb[Kqb.uuid]=true
end
local Lqb=ab.evoEats(Bqb,Iqb)
if Lqb then
ab.pickNote.autoEvolve=Lqb
return
end
if(ab.evoBlocked[Bqb.uuid]or 0)>=os.time()then
return
end
local Mqb,Nqb=ab.evolve(Bqb,rcf[3919])
if Mqb then
ab.pickDone(rcf[3915],rcf[3904],Nqb)
else
ab.evoBlocked[Bqb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=Nqb
end
end
