end
end
for Ktb,Ltb in ipairs(Ctb)do
if Ltb.train==rcf[3994]or(Ltb.train==rcf[3995]and Gtb)then
Ltb.gain=math.max(Ltb.gain,Htb*Ltb.cost*1.05)
