if iub then
local jub=tonumber(eub.what==rcf[3352]and iub.total_kills or iub.total_takedowns)or 0
if jub<eub.need then
local kub=(fub==0 and 1000 or 0)+(tonumber(dub.tierRank)or 0)*10-cub*0.01
if not _tb or kub>aub then
_tb,aub={uuid=dub.uuid,id=dub.from,to=dub.to,what=eub.what,have=jub,need=eub.need},kub
end
