local uub,vub=ib.now()
local wub={}
for xub,yub in ipairs(P.savedTeam or{})do
wub[xub]=yub
end
table.sort(wub)
if not(uub and tub.uuid==uub.uuid and(tub.base==vub or tub.base==table.concat(wub,rcf[3387])))or not ib.eligible(rub)then
return 0,1
end
local zub=ib.perRun(rub.key,uub.id)or 0
