if ib.eligible(Iub)then
local Jub=P.trainSim[Iub.key]
local Kub=Jub and Jub.uuid==Bub.uuid and os.time()-(Jub.at or 0)<6*3600
local Lub=ib.plan(Iub,Bub,Cub)
if not Kub then
Gub=Gub+1
