function ib.bestInfinite()
local Nub,Oub
for Pub,Qub in ipairs(W.lastScored or{})do
if Qub.kind==rcf[2689]and ib.eligible(Qub)then
local Rub,Sub=P.train.real[Qub.key],Qub.rec or W.rec(Qub.key)
local Tub=(tonumber(Sub.timed)or 0)>0 and Sub.sec/Sub.timed/60 or 0
local Uub=(Rub and Rub.n>0 and Tub>0)and(Rub.sum/Rub.n)/Tub or 0
if Uub<=0 then
Uub=db.hiveTrainRate(Qub.key)or 0
end
if Uub>(Oub or 0)then
Nub,Oub=Qub,Uub
end
end
end
return Nub
end
function ib.ratio()
local Vub=P.train.cal
if not(Vub and(Vub.n or 0)>0 and(Vub.sim or 0)>0)then
return 1
end
return U.clamp(Vub.real/Vub.sim,0.05,2)
end
function ib.perRun(Wub,Xub)
local Yub=P.train.real[Wub]
if Yub and Yub.n>0 then
return Yub.sum/Yub.n,true
end
local Zub=db.hiveTrain(Wub,Xub)
if Zub then
return Zub,true
end
local avb,bvb=0,0
local cvb=W.isInf(Wub)
for dvb,evb in pairs(P.train.real)do
if W.isInf(dvb)==cvb then
avb,bvb=avb+evb.sum,bvb+evb.n
end
end
if bvb>0 then
return avb/bvb,true
end
local fvb=P.trainSim[Wub]
return fvb and fvb.tk and fvb.tk*ib.ratio()or nil,false
end
function ib.eligible(gvb)
if gvb.kind==rcf[3133]or gvb.kind==rcf[2684]then
return false,rcf[3997]
end
if gvb.kind==rcf[2690]then
return false,rcf[3998]
end
if gvb.kind==rcf[3136]then
return false,rcf[3999]
end
if P.labForce and P.labForce==gvb.key then
return false,rcf[4000]
end
if N.Levels[gvb.level]and N.Levels[gvb.level]._randomequippedmode then
return false,rcf[4001]
end
if(P.train.bad[gvb.key]or 0)>os.time()then
return false,rcf[4002]..os.date(rcf[3884],P.train.bad[gvb.key])
end
local hvb=gvb.rec or W.rec(gvb.key)
if hvb.runs>=3 and hvb.wins/hvb.runs<0.8 then
return false,rcf[4003]
end
local ivb=P.simRes[gvb.key]
if ivb and ivb.trust and not ivb.trust.ok then
return false,rcf[4004]
end
return true
end
function ib.plan(jvb,kvb,lvb)
local mvb=N.session()
local nvb=table.clone(lvb)
table.sort(nvb)
local ovb=table.concat(nvb,rcf[3387])
local pvb=(tonumber((P.simCal[jvb.key]or{}).n)or 0)>0
local qvb=pvb and 1.3 or 2
local rvb=ovb..rcf[2996]..kvb.uuid..(pvb and rcf[4005]or rcf[4006])..rcf[4007]
local svb=P.trainSim[jvb.key]
if svb and svb.sig==rvb and not svb.pending and os.time()-(svb.at or 0)<6*3600 then
return svb
end
local tvb={sig=rvb,base=ovb,uuid=kvb.uuid,at=os.time(),ok=false,margin=qvb,pending=true}
P.trainSim[jvb.key]=tvb
local uvb,vvb=gb.levelFor(jvb)
if jvb.ldOverride then
uvb=jvb.ldOverride
end
if not uvb then
tvb.why,tvb.pending=rcf[4008],nil
return tvb
end
local wvb=gb.info(uvb,jvb.key,vvb,jvb.mod)
local xvb={}
for yvb,zvb in ipairs(lvb)do
local Avb=mvb.collection:get_unit_by_uuid(zvb)
if Avb then
table.insert(xvb,Avb)
end
end
local Bvb=mvb.collection:get_unit_by_uuid(kvb.uuid)
if not Bvb or#xvb==0 then
tvb.why,tvb.pending=rcf[4009],nil
return tvb
end
local Cvb=gb.run(wvb,gb.teamFrom(xvb,wvb.map),{hpMul=1})
local Dvb=wvb.infinite and gb.unbound(uvb)
local Evb=Dvb and W.infTier(gb.run(wvb,gb.teamFrom(xvb,wvb.map),{hpMul=qvb}).wave)or nil
local Fvb={}
for Gvb,Hvb in ipairs(xvb)do
if not V.isFarm(Hvb.unit_id)then
local Ivb,Jvb=pcall(V.score,Hvb,jvb.mod)
table.insert(Fvb,{i=Gvb,sc=Ivb and Jvb or 0})
end
end
table.sort(Fvb,function(Kvb,Lvb)
return Kvb.sc<Lvb.sc
end)
local Mvb
for Nvb=1,math.min(3,#Fvb)do
local Ovb=table.clone(xvb)
Ovb[Fvb[Nvb].i]=Bvb
local Pvb=gb.teamFrom(Ovb,wvb.map)
local Qvb=gb.run(wvb,Pvb,{hpMul=qvb,train=kvb.uuid})
if(Dvb and W.infTier(Qvb.wave)>=Evb)or(not Dvb and Qvb.won)then
local Rvb=gb.run(wvb,Pvb,{hpMul=1,train=kvb.uuid})
local Svb=(Rvb.tk or 0)/math.max(0.5,Rvb.t/60)
if(Rvb.won or Dvb)and(not Mvb or Svb>math.max(Mvb.rate*1.5,Mvb.rate+1))then
Mvb={out=xvb[Fvb[Nvb].i].unit_id,r=Rvb,rate=Svb,trial=Ovb}
end
end
end
tvb.ownMin=Cvb.t/60
if not Mvb then
tvb.why=Dvb and string.format(rcf[4010],Evb,pvb and rcf[4011]or rcf[4012])or pvb and rcf[4013]or rcf[4014]
else
tvb.out,tvb.tk,tvb.minutes=Mvb.out,Mvb.r.tk or 0,Mvb.r.t/60
tvb.uuids={}
for Tvb,Uvb in ipairs(Mvb.trial)do
table.insert(tvb.uuids,Uvb.uuid)
end
tvb.slow=(Cvb.won and not Dvb)and tvb.minutes/math.max(0.1,tvb.ownMin)or 1
if tvb.tk<=0 and next(P.train.real)==nil then
tvb.why=rcf[4015]
elseif tvb.slow>ib.SLOW then
tvb.why=string.format(rcf[4016],math.floor((tvb.slow-1)*100+0.5))
else
tvb.ok=true
end
end
tvb.pending=nil
F.log(1,rcf[4017],string.format(rcf[4018],jvb.label,V.name(kvb.id),tvb.out and(rcf[4019]..V.name(tvb.out))or rcf[1580],tvb.ok and string.format(rcf[4020],math.floor((ib.perRun(jvb.key,kvb.id)or 0)+0.5),kvb.what,tvb.minutes,tvb.ownMin)or tostring(tvb.why)))
F.saveSoon()
return tvb
end
