function eb.upgradeGain(uRb,vRb,wRb,xRb,yRb,zRb)
local ARb,BRb=vRb[wRb],vRb[wRb+1]
local CRb=(ARb.cd>0 and ARb.damage/ARb.cd or 0)
local DRb=(BRb.cd>0 and BRb.damage/BRb.cd or 0)*V.aoeUp(BRb.atk,BRb.range)/math.max(0.3,V.aoeUp(ARb.atk,ARb.range))
local ERb=CRb>0 and uRb*(DRb/CRb-1)or(zRb or 0)
local FRb=vRb[wRb+2]
if FRb and wRb+1<vRb.max and FRb.cd>0 and BRb.cd>0 and CRb>0 then
local GRb=uRb*((FRb.damage/FRb.cd)/CRb-1)
local HRb=xRb+FRb.cost*yRb
if GRb/HRb>ERb/xRb then
ERb=ERb+(GRb/HRb*xRb-ERb)*0.5
end
end
local IRb=(BRb.range or 0)>(ARb.range or 0)and(1+((BRb.range-ARb.range)/math.max(1,ARb.range)))or 1
return math.max(0,ERb)*IRb
end
function eb.dpsFor(JRb,KRb)
if KRb<=0 then
return 0
end
local LRb={}
for MRb,NRb in ipairs(JRb)do
if not NRb.farm and not NRb.grif and NRb.gain>0 then
table.insert(LRb,NRb)
end
end
table.sort(LRb,function(ORb,PRb)
return ORb.gain/ORb.cost>PRb.gain/PRb.cost
end)
local QRb,RRb=0,0
for SRb,TRb in ipairs(LRb)do
if KRb<=0 then
break
end
RRb=TRb.gain/TRb.cost
local URb=math.min(1,KRb/TRb.cost)
QRb=QRb+TRb.gain*URb
KRb=KRb-TRb.cost*URb
end
return QRb+math.max(0,KRb)*RRb*0.7
end
function eb.shieldDps(VRb,WRb,XRb,YRb,ZRb,_Rb,aSb)
if(YRb or 0)<=0 or(VRb or 0)<=0 or(ZRb or 0)<=0 then
return VRb or 0
end
WRb,XRb,_Rb=math.max(0.3,WRb or 2),math.max(1,XRb or 1),_Rb or 1
local bSb=VRb*_Rb*WRb/XRb
return ZRb*XRb/((YRb/math.max(1,aSb or 1)+math.max(1,ZRb/bSb))*WRb)/_Rb
end
function eb.shieldGain(cSb,dSb,eSb,fSb,gSb,hSb,iSb,jSb)
local kSb,lSb=V.attackInfo(dSb.atk,dSb.range),V.attackInfo(fSb.atk,fSb.range)
local mSb=eb.shieldDps(cSb,(tonumber(dSb.cd)or 2)*(iSb or 1),kSb.n,gSb,hSb,jSb,kSb.hits)
local nSb=eb.shieldDps(eSb,(tonumber(fSb.cd)or 2)*(iSb or 1),lSb.n,gSb,hSb,jSb,lSb.hits)
local oSb=math.max(0,((tonumber(fSb.range)or 0)-(tonumber(dSb.range)or 0))/math.max(1,tonumber(dSb.range)or 1))
return math.max(0,nSb-mSb)+mSb*oSb
end
function eb.shieldGainAhead(pSb,qSb,rSb,sSb,tSb,uSb)
local vSb=0
for wSb,xSb in ipairs(tSb or{})do
vSb=vSb+(tonumber(xSb.h)or 0)
end
if vSb<=0 then
return nil
end
local ySb=0
for zSb,ASb in ipairs(tSb)do
if(ASb.h or 0)>0 then
ySb=ySb+ASb.h/vSb*eb.shieldGain(pSb,qSb,rSb,sSb,ASb.s or 0,ASb.h,1,uSb)
end
end
return ySb
end
function eb.shieldWork(BSb,CSb,DSb,ESb,FSb,GSb,HSb,ISb,JSb)
if(ESb or 0)<=0 then
return 0
end
local KSb=3*ESb*(FSb or 1)/math.max(1,GSb or 20)
if(DSb or 0)>=KSb then
return 0
end
return math.max(1,BSb or 1)*math.max(1,JSb or 1)/math.max(0.3,CSb or 2)*math.min(HSb or 0,ISb or 0)
end
function eb.holdGain(LSb,MSb,NSb,OSb)
if not LSb or(MSb or 0)<=0 then
return 0
end
local PSb,QSb=tonumber(LSb.stun)or 0,tonumber(LSb.slowTime)or 0
if PSb<=0 and QSb<=0 then
return 0
end
local RSb,SSb=PSb>0 and PSb or QSb,PSb>0 and 1 or(tonumber(LSb.slowPct)or 0.3)
local TSb=SSb*RSb/(RSb+(tonumber(LSb.ccCd)or 8))
local USb=TSb/math.max(0.1,1-TSb)
return MSb*USb*U.clamp(NSb or 0.5,0,1)*math.min(1,(tonumber(LSb.n)or 1)/2)/(1+(OSb or 0))
end
function eb.bleedGain(VSb,WSb,XSb,YSb)
if(VSb or 0)<=0 then
return 0
end
local ZSb=WSb or 0
for _Sb,aTb in ipairs(XSb or{})do
ZSb=math.max(ZSb,(tonumber(aTb.hp)or 0)*0.5)
end
return VSb*ZSb*(YSb and 0.5 or 1)
end
function eb.bleedShare(bTb,cTb,dTb,eTb)
if bTb<=0 or not cTb then
return 0
end
if eTb then
return cTb==0 and bTb or bTb/(cTb+1)
end
return dTb<cTb and bTb/(cTb-dTb)or 0
end
function eb.keepsUp(fTb,gTb,hTb,iTb,jTb)
local kTb=fTb.coming
if not(kTb and#kTb>0 and fTb.waveSec)then
return true
end
local lTb=fTb.eff or 1
local mTb=fTb.money-hTb
local nTb=(fTb.teamDps or 0)*(fTb.shieldK or 1)+(iTb or 0)*lTb+eb.dpsFor(gTb,math.max(0,mTb))*lTb
local oTb=(fTb.farmNow or 0)+(jTb or 0)
local pTb=(fTb.roadSec or 130)*U.clamp(fTb.cover or 0.6,0.1,1)
local qTb=fTb.hpAlive or 0
local rTb=math.max(0,tonumber(fTb.regen)or 0)
for sTb,tTb in ipairs(kTb)do
local uTb=nTb-rTb*(qTb+tTb.hp)
if rTb>0 and uTb<=0 then
return false,sTb,0
end
