return vsc.v>wsc.v
end)
local zsc={}
for Asc,Bsc in ipairs(qsc)do
if not rsc[Bsc.id]and#zsc<3 and Bsc.v>=ssc*0.1 and Bsc.v>=(tonumber(psc)or 0)*0.5 then
rsc[Bsc.id]=true
table.insert(zsc,Bsc.id)
end
