if Isc>=1 and(not Dsc or Dsc(Gsc))then
local Jsc=(tonumber(Hsc.s)or 0)/Isc
if Jsc>=1/3 and(not Fsc or Jsc>Fsc)then
Esc,Fsc=Gsc,Jsc
