return Lsc
end
function gb.lockTeam(Vsc,Wsc,Xsc)
local Ysc=table.clone(Vsc)
local Zsc={}
for _sc,atc in ipairs(Ysc)do
Zsc[atc.unit_id]=true
end
local btc=N.session()
for ctc in pairs(Xsc)do
if not Zsc[ctc]then
local dtc
for etc,ftc in ipairs({Wsc or{},(type(Wsc)==rcf[2664]and Wsc.rest)or{}})do
for gtc,htc in ipairs(ftc)do
if htc.unit_id==ctc then
dtc=htc
break
end
end
if dtc then
break
end
end
if not dtc and btc then
local itc
for jtc,ktc in pairs(btc.profile_data.collection.owned_units)do
if ktc.unit_id==ctc then
local ltc=btc.collection:get_unit_by_uuid(ktc.uuid)or ktc
local mtc,ntc=pcall(V.score,ltc)
ntc=mtc and tonumber(ntc)or 0
if not itc or ntc>itc then
dtc,itc=ltc,ntc
end
end
end
end
if dtc then
local otc
for ptc,qtc in ipairs(Ysc)do
if not Xsc[qtc.unit_id]and V.sameGroup(qtc.unit_id,ctc)then
otc=ptc
end
end
if not otc and#Ysc<6 then
table.insert(Ysc,dtc)
else
if not otc then
local rtc=0
for stc,ttc in ipairs(Ysc)do
if V.isFarm(ttc.unit_id)then
rtc=rtc+1
end
end
local utc
for vtc,wtc in ipairs(Ysc)do
if not Xsc[wtc.unit_id]and not(V.isFarm(wtc.unit_id)and rtc<=1)then
local xtc,ytc=pcall(V.score,wtc)
ytc=V.isFarm(wtc.unit_id)and math.huge or(xtc and tonumber(ytc)or 0)
if not utc or ytc<utc then
otc,utc=vtc,ytc
end
end
end
end
if otc then
Ysc[otc]=dtc
end
end
Zsc[ctc]=true
end
end
end
return Ysc
end
function gb.bestTeam(ztc,Atc,Btc,Ctc)
local Dtc=U.now()
Ctc=Ctc or 25
local Etc=table.clone(Atc)
local Ftc=gb.lockIds(ztc)
if next(Ftc)then
local Gtc,Htc=pcall(gb.lockTeam,Etc,Btc,Ftc)
if Gtc and type(Htc)==rcf[2664]then
Etc=Htc
end
end
local function Itc(Jtc)
return Jtc~=nil and Ftc[Jtc.unit_id]==true
end
local Ktc,Ltc=gb.cliff(ztc,gb.teamFrom(Etc,ztc.map))
local function Mtc(Ntc)
local Otc=0
for Ptc,Qtc in ipairs(Ntc)do
if V.isFarm(Qtc.unit_id)then
Otc=Otc+1
end
end
return Otc
end
local Rtc=Mtc(Btc)>0
local function Stc(Ttc)
local Utc=0
for Vtc,Wtc in ipairs(Ttc)do
if not V.isFarm(Wtc.unit_id)and not V.allyBuff(Wtc.unit_id)then
Utc=Utc+V.cap(Wtc)
end
end
return Utc
end
local Xtc
while#Etc<6 do
local Ytc,Ztc
local _tc=Rtc and Mtc(Etc)==0
for auc,buc in ipairs(Btc)do
local cuc=false
for duc,euc in ipairs(Etc)do
if V.sameGroup(euc.unit_id,buc.unit_id)then
cuc=true
end
end
if not cuc and(not _tc or V.isFarm(buc.unit_id))then
local fuc=table.clone(Etc)
table.insert(fuc,buc)
local guc=gb.run(ztc,gb.teamFrom(fuc,ztc.map),{hpMul=Ktc})
local huc=gb.objective(guc)
if not Ztc or huc>Ztc then
Ytc,Ztc,Xtc=buc,huc,guc
end
end
end
if not Ytc then
break
end
table.insert(Etc,Ytc)
end
if Rtc and Mtc(Etc)==0 then
local iuc,juc
for kuc=1,#Etc do
for luc,muc in ipairs(Itc(Etc[kuc])and{}or Btc)do
if V.isFarm(muc.unit_id)then
local nuc=table.clone(Etc)
nuc[kuc]=muc
local ouc=gb.run(ztc,gb.teamFrom(nuc,ztc.map),{hpMul=Ktc})
local puc=gb.objective(ouc)
if not juc or puc>juc then
iuc,juc,Xtc=nuc,puc,ouc
end
end
end
end
if iuc then
Etc=iuc
end
end
local function quc(ruc,suc)
local tuc=gb.teamFrom(ruc,ztc.map)
return(gb.objective(suc)+gb.objective(gb.run(ztc,tuc,{hpMul=Ktc*0.92}))+gb.objective(gb.run(ztc,tuc,{hpMul=Ktc*1.08})))/3
end
local uuc,vuc=Xtc or Ltc,quc(Etc,Xtc or Ltc)
if type(Btc.rest)==rcf[2664]and#Btc.rest>0 then
local wuc,xuc
for yuc,zuc in ipairs(Etc)do
if not V.isFarm(zuc.unit_id)and not V.allyBuff(zuc.unit_id)and not Itc(zuc)then
local Auc,Buc=pcall(V.score,zuc,ztc.mod)
Buc=(Auc and Buc or 0)*V.skinMul(zuc,ztc.skinSet)*V.eventMul(zuc,ztc.ld)
if not xuc or Buc<xuc then
wuc,xuc=yuc,Buc
end
end
end
if wuc then
local Cuc,Duc={},U.now()
for Euc,Fuc in ipairs(Btc.rest)do
if U.now()-Duc>5 then
break
end
local Guc=false
for Huc,Iuc in ipairs(Etc)do
if V.sameGroup(Iuc.unit_id,Fuc.unit_id)then
Guc=true
end
end
if not Guc then
local Juc=table.clone(Etc)
Juc[wuc]=Fuc
table.insert(Cuc,{u=Fuc,o=gb.objective(gb.run(ztc,gb.teamFrom(Juc,ztc.map),{hpMul=Ktc}))})
end
end
table.sort(Cuc,function(Kuc,Luc)
return Kuc.o>Luc.o
end)
Btc=table.clone(Btc)
for Muc=1,math.min(4,#Cuc)do
table.insert(Btc,1,Cuc[Muc].u)
end
Dtc=Dtc+(U.now()-Duc)
end
end
for Nuc=1,2 do
local Ouc=false
for Puc=1,#Etc do
for Quc,Ruc in ipairs(Itc(Etc[Puc])and{}or Btc)do
if U.now()-Dtc>Ctc then
return Etc,uuc,Ktc,Ltc
end
local Suc=false
for Tuc,Uuc in ipairs(Etc)do
if Tuc~=Puc and V.sameGroup(Uuc.unit_id,Ruc.unit_id)then
Suc=true
end
end
if Etc[Puc]and Etc[Puc].unit_id==Ruc.unit_id then
Suc=true
end
if not Suc then
local Vuc=table.clone(Etc)
Vuc[Puc]=Ruc
if(not Rtc or Mtc(Vuc)>0)and Stc(Vuc)>=math.min(8,Stc(Etc))then
local Wuc=gb.run(ztc,gb.teamFrom(Vuc,ztc.map),{hpMul=Ktc})
local Xuc=gb.objective(Wuc)
if Xuc>vuc+1 then
Xuc=quc(Vuc,Wuc)
if Xuc>vuc+1 then
Etc,vuc,uuc,Ouc=Vuc,Xuc,Wuc,true
end
end
end
end
end
end
if not Ouc then
break
end
end
return Etc,uuc,Ktc,Ltc
end
function gb.evolutions()
