wCc=wCc+100*BCc/math.max(0.2,1-BCc)
elseif ACc.type==rcf[4811]and ACc.stat==rcf[2934]then
wCc=wCc+50*BCc
elseif ACc.type==rcf[4812]and ACc.stat==rcf[4813]then
