elseif ACc.type==rcf[4812]and ACc.stat==rcf[4814]then
wCc=wCc+100*BCc*jb.share(rcf[2854])
elseif ACc.type==rcf[4812]and ACc.stat==rcf[4815]then
wCc=wCc+100*BCc*jb.share(rcf[4654])
elseif ACc.type==rcf[4816]and ACc.stat==rcf[4817]then
wCc=wCc+60*BCc*jb.share(rcf[2856])
elseif ACc.type==rcf[4818]then
wCc=wCc+40*BCc
elseif ACc.type==rcf[4819]then
wCc=wCc+80*BCc
elseif ACc.type==rcf[4820]then
wCc=wCc+80*BCc
end
end
