jb.CURSE_COST={_curse_money=0.5,_curse_shop=0.5,_curse_health=0.5,_curse_speed=0.5,_curse_regen=0.5,_curse_shield=1,_curse_explode=1.5,_curse_random=2,_curse_super_health=1,_curse_super_speed=1,_curse_super_regen=1,_curse_super_armored=3,_curse_super_burst=1,_curse_super_explode=3,_curse_super_chaos=3}
function jb.curseCost(CCc)
if CCc==rcf[4821]then
local DCc,ECc=0,0
for FCc,GCc in ipairs(V.equipped())do
local HCc=GCc.id or(GCc.u and GCc.u.unit_id)
if HCc and not V.isFarm(HCc)then
DCc=DCc+1
local ICc,JCc=pcall(V.airFrom,HCc)
if ICc and JCc then
ECc=ECc+(JCc==0 and 1 or 0.5)
end
end
end
return 1+2*(DCc>0 and 1-ECc/DCc or 0.5)
end
return jb.CURSE_COST[CCc]or 1.5
end
function jb.roomValue(KCc,LCc)
local MCc,NCc=KCc.tags,KCc.d
local OCc=0
if MCc[jb.T.GOLD]then
OCc=OCc+12
end
if MCc[jb.T.CHEST]then
OCc=OCc+4
end
if MCc[jb.T.MONEY]then
OCc=OCc+(NCc<=15 and 2 or 0.5)
end
if MCc[jb.T.SHOP]then
if NCc>=10 and NCc<=15 then
OCc=OCc+(LCc>=300 and 5 or 1)
else
OCc=OCc+(LCc>=300 and(NCc>15 and 3 or 1)or 0.3)
end
end
if MCc[jb.T.SHRINE]then
OCc=OCc+1.5
end
if MCc[jb.T.CURSE]then
OCc=OCc-jb.curseCost(jb.roomCurse(KCc.r))
end
return OCc
end
function jb.mod(PCc)
