for TCc,UCc in pairs(type(PCc)==rcf[2664]and type(PCc._strong_against)==rcf[2664]and PCc._strong_against or{})do
QCc.strong[type(UCc)==rcf[2664]and UCc.damage_type or UCc]=true
end
