elseif gDc.type==rcf[4820]then
aDc.cost=aDc.cost+hDc
elseif gDc.type==rcf[4824]and gDc.stat==rcf[4354]then
aDc.hp=aDc.hp+hDc
elseif gDc.type==rcf[4819]then
aDc.speed=aDc.speed+hDc
elseif gDc.type==rcf[4825]then
aDc.regen=aDc.regen+hDc
elseif gDc.type==rcf[4826]then
aDc.shield=aDc.shield+hDc
elseif gDc.type==rcf[4827]and gDc.passive==rcf[4828]then
aDc.fly=aDc.fly+hDc
