function jb.sim(qDc,rDc,sDc)
if not O.sim or type(qDc.r._l)~=rcf[2664]then
return nil
end
local tDc=tostring(qDc.r._r or(qDc.d..rcf[2817]..qDc.choice))..(rDc and(rcf[2996]..tostring(rDc))or rcf[1580])..(sDc and rcf[4837]or rcf[1580])
local uDc=jb.data()
local vDc=jb.fx(uDc,jb.roomCurse(qDc.r),rDc)
local wDc=W.teamSig()..rcf[2677]..jb.fxText(vDc)..(O.killZone~=false and rcf[4838]or rcf[1580])..(bb.forcedWay()and(rcf[2677]..tostring(O.placeMode))or rcf[1580])
local xDc=P.dg.sim[tDc]
if xDc and xDc.sig==wDc then
return not xDc.none and xDc or nil
end
local yDc={}
for zDc,ADc in ipairs(V.equipped())do
table.insert(yDc,ADc.u)
end
if#yDc==0 then
return nil
end
local BDc=gb.applyFx(gb.info(gb.slim(qDc.r._l),rcf[3452],nil,jb.mod(qDc.r._l)),vDc)
jb.applyK(BDc,qDc.r._r)
if sDc then
BDc.zone=false
end
local CDc=gb.wave(BDc,1,true)
if#CDc==0 then
xDc={none=true,sig=wDc,at=os.time()}
else
local DDc=gb.evaluate(BDc,gb.teamFrom(yDc,BDc.map))
xDc={p=DDc.p,wave=DDc.wave,won=DDc.won,total=BDc.total,margin=DDc.margin,sig=wDc,at=os.time(),zone=BDc.zone~=false or nil}
end
P.dg.sim[tDc]=xDc
if U.count(P.dg.sim)>60 then
local EDc,FDc
for GDc,HDc in pairs(P.dg.sim)do
if not FDc or(HDc.at or 0)<FDc then
EDc,FDc=GDc,HDc.at or 0
end
end
P.dg.sim[EDc]=nil
end
F.saveSoon()
return not xDc.none and xDc or nil
end
function jb.winP(IDc)
local JDc=tostring(math.min(4,math.max(1,math.ceil(IDc.d/5))))
local KDc=P.dg.depth[JDc]or{runs=0,wins=0}
local LDc=U.clamp(0.95-0.015*IDc.d,0.5,0.95)
local MDc=((tonumber(KDc.wins)or 0)+LDc*2)/((tonumber(KDc.runs)or 0)+2)
local NDc,ODc=pcall(jb.sim,IDc)
if NDc and ODc and ODc.p then
local PDc,QDc=pcall(gb.styleP,ODc,ODc.zone==false and rcf[4668]or(ODc.zone and rcf[4603]or nil))
MDc=(MDc*2+(PDc and QDc or ODc.p))/3
end
return MDc,NDc and ODc or nil
end
function jb.hopeless(RDc)
