function jb.curseOk(aEc,bEc,cEc,dEc,eEc)
local fEc=tostring((jb.item(aEc)or{}).name or aEc)
local gEc,hEc,iEc=jb.curseBar(bEc,cEc)
if gEc>0.2 and jb.blindCurse(bEc,aEc)then
return false,string.format(rcf[4842],fEc,iEc)
end
local function jEc(kEc)
return kEc==nil or(tonumber(kEc.p)or 1)>=gEc
end
if dEc then
local lEc,mEc=pcall(jb.sim,dEc,nil,true)
if lEc and not jEc(mEc)then
return false,string.format(rcf[4843],fEc,(hEc:gsub(rcf[4431],rcf[4844])),tostring(mEc.margin or rcf[2917]))
end
end
if#eEc==0 then
return true
end
local nEc
for oEc,pEc in ipairs(eEc)do
local qEc,rEc=pcall(jb.sim,pEc,aEc,true)
if not qEc or jEc(rEc)then
return true
end
if not nEc or(tonumber(rEc.p)or 0)>(tonumber(nEc.p)or 0)then
nEc=rEc
end
end
return false,string.format(rcf[4845],fEc,hEc,tostring(nEc and nEc.margin or rcf[2917]))
end
