end
function jb.payValue()
local vEc,wEc=0,0
for xEc,yEc in ipairs(P.dg.pay or{})do
if type(yEc.items)==rcf[2664]then
local zEc=tonumber(yEc.gems)or 0
for AEc,BEc in pairs(yEc.items)do
if(tonumber(BEc)or 0)>0 then
zEc=zEc+W.itemValue(AEc,BEc)
end
end
vEc,wEc=vEc+zEc,wEc+1
end
end
if wEc<5 then
return nil
end
return vEc/wEc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
