function jb.ahead(DEc,EEc,FEc,GEc)
if not EEc then
return true
end
if(DEc.elem and 1 or 0)~=(EEc.elem and 1 or 0)then
return DEc.elem==true
end
if FEc==rcf[4846]then
local HEc,IEc=math.floor((tonumber(DEc.p)or 0)*20+0.5),math.floor((tonumber(EEc.p)or 0)*20+0.5)
if HEc~=IEc then
return HEc>IEc
end
elseif FEc==rcf[4847]and(tonumber(GEc)or 0)>=2 then
local JEc,KEc=tonumber(DEc.loot)or 0,tonumber(EEc.loot)or 0
if JEc~=KEc then
return JEc>KEc
end
end
