end
return false
end
function jb.fasterTeam(PIc,QIc,RIc,SIc,TIc)
local UIc=U.now()
local function VIc(WIc)
local XIc=gb.run(PIc,gb.teamFrom(WIc,PIc.map),{hpMul=1})
return XIc and XIc.won and tonumber(XIc.t)or nil
end
local YIc=VIc(QIc)
if not YIc then
return nil
end
local ZIc={}
for _Ic,aJc in ipairs(QIc)do
ZIc[aJc.unit_id]=true
end
local bJc={}
for cJc,dJc in ipairs(RIc)do
if#bJc>=6 then
break
end
if not ZIc[dJc.unit_id]and not V.isFarm(dJc.unit_id)and not V.allyBuff(dJc.unit_id)and jb.weakMatch(dJc.unit_id,SIc)then
ZIc[dJc.unit_id]=true
table.insert(bJc,dJc)
end
end
if#bJc==0 then
return nil
end
local eJc,fJc,gJc=table.clone(QIc),YIc,{}
local hJc=gb.lockIds()
for iJc,jJc in ipairs(QIc)do
if U.now()-UIc>TIc then
break
end
if not hJc[jJc.unit_id]and not V.isFarm(jJc.unit_id)and not V.allyBuff(jJc.unit_id)and not jb.weakMatch(jJc.unit_id,SIc)then
local kJc,lJc
for mJc,nJc in ipairs(bJc)do
if U.now()-UIc>TIc then
break
end
if not gJc[nJc.uuid]then
local oJc=table.clone(eJc)
oJc[iJc]=nJc
local pJc=VIc(oJc)
if pJc and pJc<(lJc or fJc)then
kJc,lJc=nJc,pJc
end
end
end
if kJc then
eJc[iJc]=kJc
gJc[kJc.uuid]=true
fJc=lJc
end
task.wait()
end
end
if fJc<YIc then
return eJc,YIc,fJc
end
return nil
end
function jb.lostSwap(qJc,rJc,sJc)
if sJc or type(qJc)~=rcf[2664]or type(rJc)~=rcf[2664]then
return false
end
return(qJc.lostHere or 0)>(rJc.lostHere or 0)and(rJc.score or 0)>(qJc.score or 0)and(rJc.wins or 0)>0
end
function jb.weakSlot(tJc)
local uJc,vJc
for wJc,xJc in ipairs(tJc or{})do
if not xJc.farm and not xJc.buff and not xJc.kept and(not vJc or(xJc.score or 0)<vJc)then
uJc,vJc=wJc,xJc.score or 0
end
end
return uJc
end
