for tTc,uTc in ipairs(bb.samples)do
if uTc.prog>sTc then
local vTc=U.flat(uTc.pos)
for wTc,xTc in ipairs(nTc)do
if(vTc-xTc.p).Magnitude<=xTc.r then
if uTc.prog>rTc then
rTc=uTc.prog
