Rdd.sec,Rdd.wave=type(Rdd.sec)==rcf[2664]and Rdd.sec or{},type(Rdd.wave)==rcf[2664]and Rdd.wave or{}
if Sdd and tonumber(Tdd)then
table.insert(Rdd.sec,math.floor(Tdd+0.5))
end
table.insert(Rdd.wave,tonumber(Udd)or 0)
if tonumber(Vdd)then
Rdd.kills=type(Rdd.kills)==rcf[2664]and Rdd.kills or{}
table.insert(Rdd.kills,math.floor(tonumber(Vdd)))
while#Rdd.kills>bb.LAYOUT_KEEP do
