function bb.layoutJudge(Wdd,Xdd,Ydd,Zdd,_dd)
_dd=_dd or rcf[5205]
local aed,bed=tonumber(Wdd and Wdd.runs)or 0,tonumber(Xdd and Xdd.runs)or 0
