if Zdd and type(Wdd.kills)==rcf[2664]and type(Xdd.kills)==rcf[2664]and#Wdd.kills>=1 and#Xdd.kills>=bb.LAYOUT_CONTROL then
local ced,ded=bb.labMedian(Wdd.kills),bb.labMedian(Xdd.kills)
if ced and ded and ced<ded*0.97 and(#Wdd.kills>=2 or ced<ded*0.85)then
