local eed,ged=(tonumber(Wdd.wins)or 0)/aed,(tonumber(Xdd.wins)or 0)/bed
if not Ydd and ged>=0.5 then
if eed+0.25<ged and(aed>=2 or(eed==0 and ged>=0.9 and bed>=3))then
return string.format(rcf[5207],tonumber(Wdd.wins)or 0,aed,aed==1 and rcf[1580]or rcf[2508],tonumber(Xdd.wins)or 0,bed,_dd)
end
local hed,ied=bb.labMedian(Wdd.sec),bb.labMedian(Xdd.sec)
if hed and ied and hed>ied*1.10 and(#Wdd.sec>=2 or hed>ied*1.25)then
return string.format(rcf[5208],math.floor(hed/60),hed%60,math.floor(ied/60),ied%60,_dd)
end
