end
return nil
end
function bb.layoutResult(led,med)
local ned=bb.info
local oed=bb.layoutSrc
if not(ned and oed)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not ned.timeLimit then
return
end
local ped=bb.wave()
local qed=bb.layoutRecFor(ned,true)
qed.at=os.time()
local sed=ned.timeLimit~=nil
local ted=ned.killScore and true or nil
local ued=ted and(bb.killsEnd or bb.realKills())or nil
if oed==rcf[5172]then
local ved=bb.bookFor(ned)
if not ved then
return
end
ved.real=type(ved.real)==rcf[2664]and ved.real or{}
bb.layoutAdd(ved.real,led,med,ped,ued)
local wed=ved.aside==nil and bb.layoutJudge(ved.real,qed.own,sed,ted)or nil
if wed then
ved.aside={at=os.time(),why=wed}
F.log(1,rcf[5101],string.format(rcf[5210],wed))
end
elseif oed==rcf[4498]then
qed.hiveUnit=type(qed.hiveUnit)==rcf[2664]and qed.hiveUnit or{}
local xed=qed.hiveUnit
bb.layoutAdd(xed,led,med,ped,ued)
local yed=bb.bookFor(ned)
local zed=yed and type(yed.real)==rcf[2664]and(tonumber(yed.real.runs)or 0)>=bb.LAYOUT_CONTROL
local Aed=zed and yed.real or qed.own
local Bed=bb.layoutJudge(xed,Aed,sed,ted,zed and rcf[5211]or nil)
if Bed then
xed.aside,xed.why=os.time(),Bed
F.log(1,rcf[5101],string.format(rcf[5212],Bed))
elseif(tonumber(xed.runs)or 0)>=bb.HIVE_TRIALS then
local Ced=Aed and bb.layoutJudge(Aed,xed,sed,ted,rcf[5213])
if Ced and yed and type(bb.hiveUnitPlan)==rcf[2664]then
for Ded,Eed in pairs(bb.hiveUnitPlan)do
yed.spots[Ded]=Eed
end
yed.real={runs=xed.runs,wins=xed.wins,sec=xed.sec,wave=xed.wave,kills=xed.kills}
yed.hive,yed.aside=os.time(),nil
qed.hiveUnit=nil
F.log(1,rcf[5101],string.format(rcf[5214],Ced))
else
xed.aside,xed.why=os.time(),rcf[5215]
F.log(1,rcf[5101],rcf[5216])
end
end
else
qed[oed]=type(qed[oed])==rcf[2664]and qed[oed]or{}
local Fed=qed[oed]
bb.layoutAdd(Fed,led,med,ped,ued)
if oed==rcf[4497]and Fed.aside==nil then
local Ged=bb.layoutJudge(Fed,qed.own,sed,ted)
if Ged then
Fed.aside,Fed.why=os.time(),Ged
F.log(1,rcf[5101],string.format(rcf[5217],Ged))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={rcf[5218],rcf[5219],rcf[5220],rcf[5221]}
function bb.controlSpot(Hed,Ied)
if not bb.killZone()then
return nil
end
local Jed=gb.holds
if not Jed(Hed.id)or V.toggleOf(Hed.id)then
return nil
end
local Ked,Led,Med,Ned=1,0,0,{}
local Oed=bb.hurtSamples()
for Ped,Qed in ipairs(bb.mine or{})do
local Red=Qed._stats
local Sed=Red.id.Value
if Red:FindFirstChild(rcf[2934])and not V.isFarm(Sed)and not V.allyBuff(Sed)then
local Ted,Ued=U.flat(Qed:GetPivot().Position),Red.range.Value
if Jed(Sed)and not V.toggleOf(Sed)then
Med=Med+1
table.insert(Ned,{p=Ted,r=Ued})
else
for Ved,Wed in ipairs(Oed)do
if(U.flat(Wed.pos)-Ted).Magnitude<=Ued then
Ked,Led=math.min(Ked,Wed.prog),math.max(Led,Wed.prog)
end
end
end
end
end
if Led<=Ked then
Ked,Led=0.75,0.98
end
local Xed=(Ied or Med)+1
local Yed=({Ked,Led,(Ked+Led)/2,Ked-(Led-Ked)/2})[Xed]
if not Yed then
return nil
end
local Zed=V.range(Hed.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local _ed={}
for afd,bfd in ipairs(bb.cands)do
local cfd,dfd,efd=U.flat(bfd),0,0
for ffd,gfd in ipairs(Oed)do
if(U.flat(gfd.pos)-cfd).Magnitude<=Zed then
efd=efd+1
if math.abs(gfd.prog-Yed)<=0.05 then
dfd=dfd+1
local hfd=U.flat(gfd.pos)
for ifd,jfd in ipairs(Ned)do
if(hfd-jfd.p).Magnitude<=jfd.r then
dfd=dfd-0.5
break
end
end
end
end
end
if dfd>0 then
table.insert(_ed,{pos=bfd,sc=dfd,cov=efd})
end
if afd%60==0 then
task.wait()
end
end
table.sort(_ed,function(kfd,lfd)
return kfd.sc>lfd.sc
end)
for mfd,nfd in ipairs(_ed)do
local ofd=bb.valid(nfd.pos,Hed.data)
if ofd then
F.log(1,rcf[5040],string.format(rcf[5222],V.name(Hed.id),bb.CONTROL_WORDS[Xed],math.floor(Yed*100+0.5)))
return ofd,nfd.cov,Yed
end
if mfd%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(pfd)
local qfd,rfd=gb.holds(pfd.id)
local sfd=false
if not qfd and bb.info and(tonumber(bb.info.regen)or 0)>0 then
local tfd,ufd=pcall(V.bleeds,pfd.id)
if tfd and ufd then
qfd,rfd,sfd=true,ufd,true
end
end
if not qfd then
return nil
end
if V.killFed(pfd.id)then
return nil
end
local vfd,wfd={},0
for xfd,yfd in ipairs(bb.mine or{})do
local zfd=yfd._stats
local Afd=zfd.id.Value
if zfd:FindFirstChild(rcf[2934])and not V.isFarm(Afd)and not V.allyBuff(Afd)and Afd~=pfd.id then
local Bfd,Cfd=pcall(bb.liveDps,yfd,Afd)
Cfd=Bfd and tonumber(Cfd)or 0
if Cfd>0 then
table.insert(vfd,{p=U.flat(yfd:GetPivot().Position),r=zfd.range.Value,d=Cfd})
wfd=wfd+Cfd
end
end
end
if#vfd==0 or wfd<=0 then
return nil
end
local Dfd=bb.hurtSamples()
local Efd={}
for Ffd,Gfd in ipairs(Dfd)do
local Hfd,Ifd=U.flat(Gfd.pos),0
for Jfd,Kfd in ipairs(vfd)do
if(Hfd-Kfd.p).Magnitude<=Kfd.r then
Ifd=Ifd+Kfd.d
end
end
Efd[Ffd]=Ifd/wfd
end
local Lfd=V.range(pfd.u,math.min(tonumber(rfd)or 0,3,V.rows(pfd.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Mfd,Nfd,Ofd
for Pfd,Qfd in ipairs(bb.cands)do
local Rfd,Sfd,Tfd=U.flat(Qfd),0,0
for Ufd,Vfd in ipairs(Dfd)do
if(U.flat(Vfd.pos)-Rfd).Magnitude<=Lfd then
Sfd=Sfd+Efd[Ufd]
Tfd=Tfd+1
end
end
if Sfd>0 and(not Nfd or Sfd>Nfd)then
local Wfd=bb.valid(Qfd,pfd.data)
if Wfd then
Mfd,Nfd,Ofd=Wfd,Sfd,Tfd
end
end
if Pfd%40==0 then
task.wait()
end
end
if not Mfd then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[pfd.id]then
bb.holdSaid[pfd.id]=true
F.log(1,rcf[5040],string.format(sfd and rcf[5223]or rcf[5224],V.name(pfd.id)))
end
return Mfd,Ofd or 0
end
function bb.buffAtSpot(Xfd,Yfd,Zfd)
local _fd={}
for agd,bgd in ipairs(type(Zfd)==rcf[2664]and Zfd or{})do
local cgd=type(bgd.b)==rcf[2664]and type(bgd.b.types)==rcf[2664]and tonumber(bgd.b.types[Yfd])or nil
if cgd and(bgd.pos-Xfd).Magnitude<=bgd.range then
local dgd=_fd[bgd.b.attack]
if not dgd then
dgd={n=0,rate=cgd,b=bgd.b}
_fd[bgd.b.attack]=dgd
end
dgd.n=dgd.n+1
if bgd.cd then
dgd.cd=math.min(dgd.cd or math.huge,bgd.cd)
end
end
end
local egd=0
for fgd,ggd in pairs(_fd)do
local hgd=math.max(1,tonumber(ggd.b.time)or 30)
local igd=math.max(1,ggd.cd or tonumber(ggd.b.cd)or 60)
local jgd=V.stackCap(fgd)
local kgd
if jgd then
kgd=math.min(jgd,(1+ggd.rate)^math.floor(ggd.n*hgd/igd+0.001)-1)
else
kgd=math.min(ggd.rate,ggd.n*ggd.rate*math.min(1,hgd/igd))
end
egd=math.max(egd,kgd)
end
return egd
end
function bb.blockSpot(lgd,mgd)
if V.isFarm(lgd.id)or V.allyBuff(lgd.id)then
return nil
end
local ngd,ogd=V.types(lgd.id)
local pgd={}
for qgd,rgd in ipairs(bb.fieldBuffers())do
if type(rgd.b.types)==rcf[2664]and rgd.b.types[ogd]then
table.insert(pgd,rgd)
end
end
if#pgd==0 then
return nil
end
local sgd=(bb.info and tonumber(bb.info.rangeScale))or 1
local tgd=V.range(lgd.u,V.rows(lgd.id).max)*sgd
local ugd=bb.buffAtSpot(mgd,ogd,pgd)
local vgd=bb.cover(mgd,tgd)
local wgd,xgd,ygd,zgd=nil,vgd*(1+ugd),ugd,vgd
local Agd=0
local Bgd=bb.newRadius(lgd)
for Cgd,Dgd in ipairs(pgd)do
for Egd,Fgd in ipairs(bb.ringSpots(Dgd.pos,(Dgd.hr or bb.HB_R)+Bgd+0.1,Dgd.range))do
local Ggd=bb.valid(Fgd,lgd.data)
Agd=Agd+1
if Agd%40==0 then
task.wait()
end
if Ggd then
local Hgd=bb.buffAtSpot(Ggd,ogd,pgd)
if Hgd>ugd+0.001 then
local Igd=bb.cover(Ggd,tgd)
local Jgd=Igd*(1+Hgd)
if Jgd>xgd then
wgd,xgd,ygd,zgd=Ggd,Jgd,Hgd,Igd
end
end
end
end
end
if not wgd then
return nil
end
F.log(1,rcf[5040],string.format(rcf[5225],V.name(lgd.id),math.floor(ygd*100+0.5),math.floor(ugd*100+0.5),math.floor(zgd/math.max(1,vgd)*100+0.5)))
return wgd
end
