local Qjd=U.flat(Hjd)
for Rjd,Sjd in ipairs(Bhd)do
if(U.flat(Sjd.pos)-Qjd).Magnitude<=Rhd then
Ijd=Ijd+Sjd.prog*Sjd.prog
end
end
elseif Thd and Pid>0 then
local Tjd=0
for Ujd,Vjd in ipairs(Oid)do
local Wjd=Vjd.pos3 and(Vjd.pos3-Hjd).Magnitude or(U.flat(Vjd.pos)-U.flat(Hjd)).Magnitude
if Wjd<=Qid then
Tjd=Tjd+Vjd.full*Vjd.w*(1.1-0.1*Wjd/math.max(1,Qid))*(Rid and bb.buffJoin(Hjd,Qid,Vjd.by)or 1)
end
end
Ijd=Tjd/Pid*100+bb.cover(Hjd,Rhd,true)*0.05
else
local Xjd=bb.cover(Hjd,Rhd,true,Ahd)
if Shd then
Xjd=bb.cover(Hjd,Shd)+Xjd*0.25
end
Ijd=Xjd+(Ejd and 0 or(1-bb.progressAt(Hjd))*0.5)
local Yjd=0
for Zjd,_jd in ipairs(Nid)do
local akd=_jd.b.types[Mid]
if akd and(U.flat(_jd.pos)-U.flat(Hjd)).Magnitude<=_jd.range then
Yjd=math.max(Yjd,math.min(akd,Yjd+akd*_jd.b.uptime))
end
end
Ijd=Ijd*(1+Yjd)
end
if ejd and(U.flat(ejd)-U.flat(Hjd)).Magnitude<=fjd then
Ijd=Ijd+1e6
end
if gjd and(U.flat(gjd)-U.flat(Hjd)).Magnitude<=hjd then
Ijd=Ijd+1e6
end
if ijd then
table.insert(ijd,{p=Hjd,sc=Ijd})
end
if not rjd or Ijd>rjd then
qjd,rjd,sjd=Hjd,Ijd,bb.cover(Hjd,Rhd)
end
end
end
if Thd and#Oid>0 and qjd then
local bkd,ckd={},0
for dkd,ekd in ipairs(Oid)do
if((ekd.pos3 or ekd.pos)-qjd).Magnitude<=Qid then
table.insert(bkd,V.name(ekd.id))
end
end
if#bkd==0 then
return nil,0
end
for fkd,gkd in ipairs(bb.fieldBuffers())do
if gkd.b.attack==Thd.attack and(gkd.pos-qjd).Magnitude<=math.min(Qid,gkd.range)then
ckd=ckd+1
end
end
F.log(1,rcf[5040],string.format(rcf[5231],V.name(Kgd.id),table.concat(bkd,rcf[2788]),ckd))
end
if ijd and#ijd>0 then
table.sort(ijd,function(hkd,ikd)
return hkd.sc>ikd.sc
end)
for jkd=1,math.min(15,#ijd)do
local kkd,lkd=ijd[jkd].p,0
for mkd=0,7 do
local nkd=mkd*math.pi/4
if bb.valid(kkd+Vector3 .new(math.cos(nkd),0,math.sin(nkd))*5,zhd)then
lkd=lkd+1
end
if lkd>=2 then
break
end
end
if lkd>=2 then
return kkd,bb.cover(kkd,Rhd)
end
end
end
return qjd,sjd or 0
