if okd.blessing then
return rcf[4804]
end
if pkd.road_unit then
return okd.knockback and rcf[5232]or rcf[5233]
end
if type(okd.aura)==rcf[2664]and#okd.aura>0 then
return rcf[2866]
end
return rcf[5234]
end
bb.BARR_DENSE=0.75
bb.BARR_TEAM,bb.BARR_WAVE=1,1
bb.BARR_GAP=0.1
function bb.barricadeOrder(qkd,rkd)
local skd,tkd={},0
for ukd,vkd in ipairs(qkd or{})do
local wkd=Vector3 .new(vkd.pos.X,0,vkd.pos.Z)
local xkd,ykd=0,math.huge
for zkd,Akd in ipairs(rkd or{})do
local Bkd=(Akd.p-wkd).Magnitude
if Bkd<=Akd.r then
xkd=xkd+1
end
if Bkd<ykd then
ykd=Bkd
end
end
if xkd>tkd then
tkd=xkd
end
table.insert(skd,{s=vkd,n=xkd,d=ykd})
end
if tkd<1 then
return{}
end
local Ckd=tkd>=2
local Dkd,Ekd={},{}
for Fkd,Gkd in ipairs(skd)do
if(Ckd and Gkd.n>=tkd*bb.BARR_DENSE)or(not Ckd and Gkd.n>=1)then
local Hkd=tostring(Gkd.s.lane)
if not Dkd[Hkd]then
Dkd[Hkd]={}
table.insert(Ekd,Hkd)
end
table.insert(Dkd[Hkd],Gkd)
end
end
table.sort(Ekd)
local Ikd=0
for Jkd,Kkd in ipairs(Ekd)do
local Lkd=Dkd[Kkd]
if not Ckd then
table.sort(Lkd,function(Mkd,Nkd)
return(Mkd.s.prog or 0)<(Nkd.s.prog or 0)
end)
for Okd=2,#Lkd do
if(Lkd[Okd].s.prog or 0)-(Lkd[Okd-1].s.prog or 0)>bb.BARR_GAP then
for Pkd= #Lkd,Okd,-1 do
table.remove(Lkd,Pkd)
end
break
end
end
table.sort(Lkd,function(Qkd,Rkd)
if Qkd.d~=Rkd.d then
return Qkd.d<Rkd.d
end
return(Qkd.s.prog or 0)>(Rkd.s.prog or 0)
end)
else
table.sort(Lkd,function(Skd,Tkd)
if Skd.n~=Tkd.n then
return Skd.n>Tkd.n
end
return(Skd.s.prog or 0)>(Tkd.s.prog or 0)
end)
end
Ikd=math.max(Ikd,#Lkd)
end
local Ukd={}
for Vkd=1,Ikd do
for Wkd,Xkd in ipairs(Ekd)do
if Dkd[Xkd][Vkd]then
table.insert(Ukd,Dkd[Xkd][Vkd].s.pos)
end
end
end
return Ukd
end
function bb.defPick(Ykd,Zkd,_kd,ald,bld,cld,dld)
local eld={}
if Ykd==rcf[2866]or Ykd==rcf[5234]then
local fld={}
local gld={}
if Ykd==rcf[5234]then
for hld,ild in ipairs(bld or{})do
local jld=U.flat(ild.pos)
for kld,lld in ipairs(_kd)do
if(lld.p-jld).Magnitude<=lld.r then
table.insert(gld,jld)
break
end
end
end
end
for mld,nld in ipairs(ald)do
local pld=U.flat(nld)
local qld,rld,sld=0,0,false
for tld,uld in ipairs(_kd)do
local vld=(uld.p-pld).Magnitude
if vld<=Zkd then
qld=qld+1
rld=rld+vld
end
if dld and vld<=dld then
sld=true
end
end
local wld=0
for xld,yld in ipairs(gld)do
if(yld-pld).Magnitude<=Zkd then
wld=wld+1
end
end
local zld=Ykd==rcf[2866]and(qld*1000-rld-(sld and 500 or 0))or(wld*1000+cld(nld,Zkd)*10+qld)
if Ykd~=rcf[2866]or qld>0 then
table.insert(fld,{p=nld,sc=zld})
end
end
table.sort(fld,function(Ald,Bld)
return Ald.sc>Bld.sc
end)
for Cld=1,math.min(1000,#fld)do
eld[Cld]=fld[Cld].p
end
elseif Ykd==rcf[5233]or Ykd==rcf[5232]then
local Dld={}
for Eld,Fld in ipairs(bld)do
local Gld=U.flat(Fld.pos)
for Hld,Ild in ipairs(_kd)do
if(Ild.p-Gld).Magnitude<=Ild.r then
table.insert(Dld,Fld)
break
end
end
end
if Ykd==rcf[5232]then
for Jld,Kld in ipairs(bb.barricadeOrder(Dld,_kd))do
table.insert(eld,Kld)
end
end
table.sort(Dld,function(Lld,Mld)
if Ykd==rcf[5233]then
return(Lld.prog or 0)<(Mld.prog or 0)
end
return(Lld.prog or 0)>(Mld.prog or 0)
end)
for Nld=3,math.min(#Dld,120)do
table.insert(eld,Dld[Nld].pos)
end
if#eld==0 and Dld[1]then
eld[1]=Dld[1].pos
end
end
return eld
end
function bb.tnWayPick(Old,Pld)
if type(Pld)~=rcf[2664]or#Old==0 then
return nil
end
local function Qld(Rld)
local Sld=Pld[Rld.style]
if type(Sld)~=rcf[2664]or(tonumber(Sld.n)or 0)<1 then
return 2,0,0
end
if(tonumber(Sld.far)or 0)<0.5*(tonumber(Rld.wave)or 0)then
return 3,tonumber(Sld.best)or 0,tonumber(Sld.far)or 0
end
return 1,tonumber(Sld.best)or 0,tonumber(Sld.far)or 0
end
local Tld,Uld,Vld,Wld
for Xld,Yld in ipairs(Old)do
local Zld,_ld,amd=Qld(Yld)
if not Tld or Zld<Uld or(Zld==Uld and Zld~=2 and(_ld>Vld or(_ld==Vld and amd>Wld)))then
Tld,Uld,Vld,Wld=Xld,Zld,_ld,amd
end
end
if Uld==2 and Tld==1 then
return nil
end
local bmd=Uld==1 and string.format(rcf[5235],Wld)or Uld==2 and rcf[5236]or string.format(rcf[5237],Wld)
return Tld,bmd
end
bb.DEF_APART=6
