function bb.defTick()
if not O.defenses or bb.finished or not(bb.ld and(bb.ld._swordsmith or bb.ld._own_defenses))then
return
end
bb.defFail=bb.defFail or{}
bb.defUsed=bb.defUsed or{}
local jnd={}
for knd,lnd in ipairs(bb.mine or{})do
local mnd=lnd:FindFirstChild(rcf[2736])
if mnd and mnd:FindFirstChild(rcf[3059])and mnd:FindFirstChild(rcf[2934])and not V.isFarm(mnd.id.Value)then
table.insert(jnd,{p=U.flat(lnd:GetPivot().Position),r=tonumber(mnd.range.Value)or 0})
end
end
if#jnd==0 then
return
end
local nnd=bb.defList()
local ond
do
local pnd=(bb.info and tonumber(bb.info.rangeScale))or 1
for qnd,rnd in ipairs(V.equipped())do
if V.allyBuff(rnd.id)and not V.isFarm(rnd.id)then
local snd,tnd=pcall(V.range,rnd.u,0)
if snd and tonumber(tnd)then
ond=math.max(ond or 0,tnd*pnd)
end
end
end
end
if#nnd==0 and not bb.defWornSaid then
bb.defWornSaid=true
local und,vnd,wnd=pcall(ab.defWorn)
if und and vnd>0 then
F.log(1,rcf[3765],string.format(rcf[5238],vnd,vnd==1 and rcf[5239]or rcf[5240],wnd,hb.have(rcf[3751]),O.defRepair and rcf[5241]or rcf[5242]))
end
end
for xnd,ynd in ipairs(nnd)do
local znd=ynd.kind==rcf[5232]and#jnd<bb.BARR_TEAM and bb.wave()<bb.BARR_WAVE
if not znd and(bb.defFail[ynd.slot]or 0)<3 and not(bb.defWait and bb.defWait[ynd.slot]and#jnd<=bb.defWait[ynd.slot])then
local And=bb.defPick(ynd.kind,ynd.range,jnd,bb.cands or{},bb.samples or{},bb.cover,ond)
local Bnd
for Cnd,Dnd in ipairs(And)do
if bb.defTaken(Dnd,bb.defUsed)then
Bnd=nil
elseif ynd.kind==rcf[5233]or ynd.kind==rcf[5232]then
local End=N.PC.raycast(Dnd+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
local Fnd,Gnd=pcall(N.PC.is_valid_raycast_hit,End and End.Instance,ynd.unit)
Bnd=End and Fnd and Gnd and End.Position or nil
else
Bnd=bb.valid(Dnd,ynd.unit)
end
if Bnd then
break
end
end
if not Bnd then
bb.defWait=bb.defWait or{}
if not bb.defWait[ynd.slot]then
F.log(1,rcf[3765],string.format(rcf[5243],ynd.name))
end
bb.defWait[ynd.slot]= #jnd
else
local Hnd,Ind=F.request(rcf[5244],rcf[4466],ynd.d.unit_uuid,N.Util.CFramePLV(Bnd,bb.lookAt(Bnd)))
table.insert(bb.defUsed,U.flat(Bnd))
if Hnd and Ind then
ynd.d.placed=true
pcall(bb.defNote,ynd,Bnd,jnd)
local Jnd=0
for Knd,Lnd in ipairs(jnd)do
if(Lnd.p-U.flat(Bnd)).Magnitude<=ynd.range then
Jnd=Jnd+1
end
end
F.log(1,rcf[3765],string.format(rcf[5245],ynd.name,bb.spotKey(Bnd),ynd.kind==rcf[2866]and string.format(rcf[5246],Jnd,#jnd)or(ynd.kind==rcf[5234]and string.format(rcf[5247],bb.cover(Bnd,ynd.range))or(ynd.kind==rcf[5233]and rcf[5248]or rcf[5249]))))
else
bb.defFail[ynd.slot]=(bb.defFail[ynd.slot]or 0)+1
if bb.defFail[ynd.slot]>=3 then
F.log(1,rcf[3765],string.format(rcf[5250],ynd.name,tostring(Ind)))
end
end
end
return
end
end
end
function bb.unplacedWhy(Mnd,Nnd)
