function bb.place(xod,yod)
local zod=V.isFarm(xod.id)
local Aod,Bod=bb.bestSpot(xod,zod or V.idol(xod.id),(bb.trainee~=nil and xod.uuid==bb.trainee)or V.ENTRY[xod.id]==true or(O.takedownFront==true and V.takedownFed(xod.id))or(bb.studyEntry==true and xod.id==bb.trialId)or bb.breakerFront(xod.id))
if not Aod then
bb.noSpot[xod.uuid]=(bb.noSpot[xod.uuid]or 0)+1
bb.noSpotField=bb.noSpotField or{}
bb.noSpotField[xod.uuid]=bb.fieldCount()
F.status(rcf[5104],rcf[5258]..V.name(xod.id))
return false
end
local Cod=bb.money()
local Dod=P.caps[xod.uuid]and bb.count(xod.uuid)or nil
local Eod,Fod=F.request(rcf[5244],rcf[4466],xod.uuid,N.Util.CFramePLV(Aod,bb.lookAt(Aod)))
if Eod and Fod then
if Dod and Dod>=(tonumber(P.caps[xod.uuid])or math.huge)then
F.log(1,rcf[5040],string.format(rcf[5259],V.name(xod.id),tostring(P.caps[xod.uuid])))
P.caps[xod.uuid],P.capsAt[xod.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(xod.data.cost or 0)
table.insert(bb.actions,string.format(rcf[5260],V.name(xod.id)))
F.log(1,rcf[5040],string.format(rcf[5261],V.name(xod.id),bb.spotKey(Aod),Bod,yod))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=xod.id,x=math.floor(Aod.X),z=math.floor(Aod.Z),cover=math.floor((Bod or 0)+0.5),why=tostring(yod):sub(1,90)})
F.status(rcf[5104],string.format(rcf[5262],V.name(xod.id),yod))
bb.placedAt=bb.placedAt or{}
bb.placedAt[xod.uuid]=(bb.placedAt[xod.uuid]or 0)+1
return true
end
if Cod>=(xod.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[xod.uuid]=(bb.placeFail[xod.uuid]or 0)+1
if bb.placeFail[xod.uuid]>=2 then
bb.noSpot[xod.uuid]=3
if bb.noSpotField then
bb.noSpotField[xod.uuid]=nil
end
F.log(1,rcf[5040],string.format(rcf[5263],V.name(xod.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Eod and Cod>=(xod.data.cost or 0)and not bb.random then
local God=bb.spotKey(Aod)
bb.refused[God]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[xod.uuid]=(bb.unitRefusals[xod.uuid]or 0)+1
if not bb.crowded()then
local Hod=bb.mapKey()
P.blocked[Hod]=P.blocked[Hod]or{}
if not bb.refusedRun[God]then
P.blocked[Hod][God]=(tonumber(P.blocked[Hod][God])or 0)+1
bb.refusedRun[God]=true
P.blockedAt[Hod]=P.blockedAt[Hod]or{}
P.blockedAt[Hod][God]=os.time()
end
if bb.unitRefusals[xod.uuid]>=3 then
local Iod=math.max(1,bb.count(xod.uuid))
if P.caps[xod.uuid]~=Iod or not V.learnedCap(xod.uuid)then
P.caps[xod.uuid],P.capsAt[xod.uuid]=Iod,os.time()
F.log(1,rcf[5040],string.format(rcf[5264],V.name(xod.id),Iod))
end
end
elseif bb.unitRefusals[xod.uuid]>=3 and(bb.noSpot[xod.uuid]or 0)<3 then
bb.noSpot[xod.uuid]=3
if bb.noSpotField then
bb.noSpotField[xod.uuid]=nil
end
F.log(1,rcf[5040],string.format(rcf[5265],V.name(xod.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,rcf[5040],string.format(rcf[5266],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,rcf[5040],rcf[5267]..God..rcf[3668]..V.name(xod.id))
F.saveSoon()
end
return false
end
function bb.crowded()
if bb.withOthers then
return true
end
return#game:GetService(rcf[1559]):GetPlayers()>1
end
bb.REFUSE_FREE,bb.REFUSE_PAUSE=10,20
function bb.placePaused()
return bb.placePause~=nil and U.now()<bb.placePause
end
function bb.count(Jod)
local Kod=0
for Lod,Mod in ipairs({workspace._UNITS,workspace:FindFirstChild(rcf[5035])})do
if Mod then
for Nod,Ood in ipairs(Mod:GetChildren())do
local Pod=Ood:FindFirstChild(rcf[2736])
if Pod and Pod:FindFirstChild(rcf[3058])and Pod.player.Value==M and Pod.uuid.Value==Jod then
Kod=Kod+1
end
end
end
end
return Kod
end
function bb.measure()
local Qod,Rod=bb.calRun,bb.info
if not(Qod and Rod)then
return
end
pcall(bb.sampleHelpers)
local Sod=U.now()
local Tod=bb.wave()
local Uod=bb.money()
if not Qod.start and Uod>0 and#bb.mine==0 then
Qod.start=Uod
end
if Tod~=Qod.lastW then
if bb.trialId and Tod>0 then
bb.trialTrace=bb.trialTrace or{}
local Vod,Wod,Xod,Yod=0,{},0,0
for Zod,_od in ipairs(bb.mine)do
local apd=_od._stats
if apd.id.Value==bb.trialId then
Vod=Vod+1
table.insert(Wod,tostring(apd.upgrade.Value))
elseif not V.isFarm(apd.id.Value)then
Yod=Yod+1
end
end
pcall(bb.sampleHelpers,true)
for bpd,cpd in pairs(bb.ownDealt)do
if cpd.id==bb.trialId then
Xod=Xod+cpd.v
end
end
local dpd=0
for epd,fpd in pairs(bb.helperDealt)do
if fpd.owner==bb.trialId then
dpd=dpd+fpd.v
end
end
table.insert(bb.trialTrace,string.format(rcf[5268],Tod,Sod-(bb.startT or Sod),Uod,table.concat(Wod,rcf[3387]),Yod,Xod+dpd,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Tod-1]or 0,bb.teamDps or 0))
end
if Qod.lastW and Qod.lastW>0 and Qod.lastWT then
table.insert(Qod.waveSec,Sod-Qod.lastWT)
end
if Qod.paidT and Tod>0 and Sod-Qod.paidT<15 then
table.insert(Qod.skip,Sod-Qod.paidT)
end
Qod.paidT=nil
if Tod>0 then
Qod.alive[tostring(Tod)]=bb.hpAliveRaw or 0
end
Qod.lastW,Qod.lastWT=Tod,Sod
end
local gpd=workspace:FindFirstChild(rcf[5269])
if gpd and Tod>0 then
Qod.timer[tostring(Tod)]=math.max(Qod.timer[tostring(Tod)]or 0,tonumber(gpd.Value)or 0)
end
local hpd=tonumber(bb.spent)or 0
local ipd=Uod-(bb.lastMoneyR or Uod)+(hpd-(bb.lastSpentR or hpd))
bb.lastMoneyR,bb.lastSpentR=Uod,hpd
bb.incomeLog=bb.incomeLog or{}
if ipd>0 then
table.insert(bb.incomeLog,{t=Sod,y=ipd})
end
while bb.incomeLog[1]and Sod-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local jpd=0
for kpd,lpd in ipairs(bb.incomeLog)do
jpd=jpd+lpd.y
end
local mpd=math.min(30,Sod-(bb.startT or Sod))
bb.incomeRate=mpd>=8 and jpd/mpd or nil
for npd,opd in ipairs(bb.enemies)do
local ppd=opd.m
local qpd=bb.track[ppd]
if not qpd then
local rpd=ppd._stats
local spd=ppd:FindFirstChildOfClass(rcf[3075])
local tpd=Rod.cfgById[rpd.id.Value]
local upd=tpd and gb.baseStats(Rod,tpd)
if spd and upd and Tod>0 then
local vpd=upd*Rod.hpRaw*gb.waveScale(Rod,Tod,Rod.list[Tod])
if vpd>0 and spd.MaxHealth>0 then
table.insert(Qod.hp,spd.MaxHealth/vpd)
end
end
bb.track[ppd]={t=Sod,p=opd.prog,sp=(rpd:FindFirstChild(rcf[5270])and tonumber(rpd.speed.Value))or 1}
if spd and spd.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+spd.MaxHealth
end
if Tod>0 then
Qod.spawn[tostring(Tod)]=(Qod.spawn[tostring(Tod)]or 0)+1
Qod.spawnLast[tostring(Tod)]=Sod-(Qod.lastWT or Sod)
end
elseif not qpd.done and Sod-qpd.t>=15 then
qpd.done=true
local wpd=(opd.prog-qpd.p)/(Sod-qpd.t)/math.max(0.1,qpd.sp)
if wpd>0.001 and opd.prog<0.95 then
table.insert(Qod.walk,wpd)
end
end
end
local xpd=0
for ypd,zpd in ipairs(bb.mine)do
local Apd=zpd._stats:FindFirstChild(rcf[3060])
if Apd then
xpd=xpd+Apd.Value
end
end
for Bpd,Cpd in pairs(bb.helperDealt or{})do
if Cpd.owner and V.SUMMONER[Cpd.owner]and not V.droneHelper(Cpd)then
xpd=xpd+(tonumber(Cpd.v)or 0)
end
end
Qod.potSum=Qod.potSum or 0
if Qod.lastDealtT then
local Dpd=Sod-Qod.lastDealtT
local Epd=0
Qod.potBy=Qod.potBy or{}
Qod.potExp=Qod.potExp or{}
for Fpd,Gpd in ipairs(bb.mine)do
local Hpd=Gpd._stats
local Ipd=Hpd.id.Value
if not V.isFarm(Ipd)and((Hpd:FindFirstChild(rcf[5271])and Hpd.target.Value~=nil)or bb.inReach(Gpd,Ipd))then
local Jpd,Kpd=pcall(bb.liveDps,Gpd,Ipd)
if Jpd and Kpd then
Epd=Epd+Kpd*Dpd
local Lpd=math.max(0.5,V.nudge(Ipd))
local Mpd=Kpd/Lpd
local Npd,Opd=pcall(function()
return V.passive(Ipd).mark
end)
if Npd and Opd and Hpd:FindFirstChild(rcf[3116])then
Mpd=Mpd+(tonumber(Opd.dot)or 0)*Hpd.damage.Value
end
Qod.potBy[Ipd]=(Qod.potBy[Ipd]or 0)+Mpd*Dpd
Qod.potExp[Ipd]=(Qod.potExp[Ipd]or 0)+Mpd*Lpd*Dpd
end
end
end
Qod.potWin=(Qod.potWin or 0)+Epd
if Sod-(Qod.winT or Sod)>=5 then
local Ppd=xpd-(Qod.winDealt or xpd)
if Qod.potWin>0 and Ppd>=0 then
Qod.dealtSum=(Qod.dealtSum or 0)+Ppd
Qod.potSum=Qod.potSum+Qod.potWin
end
Qod.winT,Qod.winDealt,Qod.potWin=Sod,xpd,0
end
end
if not Qod.winT then
Qod.winT,Qod.winDealt=Sod,xpd
end
Qod.lastDealtT=Sod
if Tod~=Qod.dpsW and Tod>0 then
Qod.dpsAt[tostring(Tod)]=bb.teamDps or 0
Qod.dpsW=Tod
end
local Qpd=math.min(1,Sod-(Qod.densT or Sod))
Qod.densT=Sod
for Rpd,Spd in ipairs(bb.enemies)do
local Tpd=math.min(gb.BINS,math.floor(Spd.prog*gb.BINS)+1)
Qod.dens[Tpd]=(Qod.dens[Tpd]or 0)+Qpd
end
local Upd=workspace._BASES.player:FindFirstChild(rcf[5272])
local Vpd=Upd and Upd:FindFirstChild(rcf[5273])
local Wpd=Vpd and Vpd:FindFirstChildOfClass(rcf[3075])
if Wpd then
Qod.baseHp=math.max(Qod.baseHp or 0,Wpd.MaxHealth)
local Xpd=0
for Ypd,Zpd in ipairs(bb.enemies)do
if Zpd.prog>=0.97 then
local _pd=Zpd.m:FindFirstChildOfClass(rcf[3075])
Xpd=Xpd+(_pd and _pd.MaxHealth or Zpd.hp)
end
end
if Qod.lastBase and Wpd.Health<Qod.lastBase and Xpd>0 and Qod.lastBaseT then
table.insert(Qod.baseRel,(Qod.lastBase-Wpd.Health)/math.max(0.1,Sod-Qod.lastBaseT)/Xpd)
end
Qod.lastBase,Qod.lastBaseT=Wpd.Health,Sod
end
end
function bb.recordMap()
local aqd=bb.mapKey()
local bqd=P.maps[aqd]
if bqd and bqd.v==1 and bqd.laneV and(bqd.densN or 0)==(bqd.binsDensN or 0)then
return
end
if bqd and bqd.v==1 and bqd.laneV and(bqd.densN or 0)>5 and(bqd.binsDensN or 0)>=5 then
return
end
local cqd={override_hitbox_radius=1.75}
local dqd={hill_unit=true,override_hitbox_radius=1.75}
local eqd,fqd={},false
for gqd,hqd in ipairs(bb.cands)do
local iqd=bb.valid(hqd,cqd,true)
if iqd then
table.insert(eqd,iqd)
end
if not fqd and bb.valid(hqd,dqd,true)then
fqd=true
end
if gqd%30==0 then
task.wait()
end
end
local jqd,kqd={},{}
local lqd=gb.laneList(bb.samples)
for mqd=5,60,5 do
local nqd,oqd
for pqd,qqd in ipairs(eqd)do
local rqd=bb.cover(qqd,mqd,true,nil,true)
if not oqd or rqd>oqd then
nqd,oqd=qqd,rqd
end
end
if nqd then
local sqd,tqd={},{}
for uqd=1,gb.BINS do
sqd[uqd]=rcf[4822]
end
for vqd,wqd in ipairs(lqd or{})do
tqd[wqd]={}
for xqd=1,gb.BINS do
tqd[wqd][xqd]=rcf[4822]
end
end
local yqd=U.flat(nqd)
for zqd,Aqd in ipairs(bb.samples)do
if(U.flat(Aqd.pos)-yqd).Magnitude<=mqd then
local Bqd=math.min(gb.BINS,math.floor(Aqd.prog*gb.BINS)+1)
sqd[Bqd]=rcf[3120]
if tqd[tostring(Aqd.lane)]then
tqd[tostring(Aqd.lane)][Bqd]=rcf[3120]
end
end
end
jqd[tostring(mqd)]=table.concat(sqd)
if lqd then
kqd[tostring(mqd)]={}
for Cqd,Dqd in pairs(tqd)do
kqd[tostring(mqd)][Cqd]=table.concat(Dqd)
end
end
end
task.wait()
end
local Eqd=P.maps[aqd]or{}
P.maps[aqd]={v=1,laneV=1,bins=jqd,binsL=lqd and kqd or nil,lanes=lqd,hill=fqd,spots= #eqd,dens=Eqd.dens,densN=Eqd.densN,binsDensN=Eqd.densN or 0,lay=Eqd.lay,walk=Eqd.walk,walkN=Eqd.walkN,sep=lqd and(select(2,pcall(gb.laneSep,bb.samples))or Eqd.sep)or nil,hidden=Eqd.hidden}
gb._masks={}
F.log(1,rcf[4587],string.format(rcf[5274],aqd,#eqd,fqd and rcf[5275]or rcf[5276]))
F.saveSoon()
end
bb.helperDealt,bb.helperAt,bb.ownDealt={},0,{}
function bb.sampleHelpers(Fqd)
if not Fqd and U.now()-bb.helperAt<3 then
return
end
bb.helperAt=U.now()
local Gqd=workspace:FindFirstChild(rcf[5016])
local Hqd={}
for Iqd,Jqd in ipairs(bb.mine or{})do
Hqd[Jqd]=true
local Kqd=Jqd:FindFirstChild(rcf[2736])
local Lqd=Kqd and Kqd:FindFirstChild(rcf[3060])
if Lqd and Kqd:FindFirstChild(rcf[3059])then
local Mqd=bb.ownDealt[Jqd]or{id=Kqd.id.Value,v=0,lvl=0}
Mqd.v=math.max(Mqd.v,Lqd.Value)
local Nqd=Kqd:FindFirstChild(rcf[5042])
Mqd.yen=math.max(Mqd.yen or 0,Nqd and tonumber(Nqd.Value)or 0)
Mqd.lvl=math.max(Mqd.lvl,Kqd:FindFirstChild(rcf[2767])and tonumber(Kqd.upgrade.Value)or 0)
bb.ownDealt[Jqd]=Mqd
end
end
for Oqd,Pqd in ipairs(Gqd and Gqd:GetChildren()or{})do
local Qqd=Pqd:FindFirstChild(rcf[2736])
local Rqd=Qqd and Qqd:FindFirstChild(rcf[5019])
local Sqd=Qqd and Qqd:FindFirstChild(rcf[3060])
if Rqd and Sqd and Rqd.Value~=nil and Hqd[Rqd.Value]then
local Tqd=Rqd.Value:FindFirstChild(rcf[2736])
local Uqd=bb.helperDealt[Pqd]or{id=Qqd.id.Value,owner=Tqd and Tqd:FindFirstChild(rcf[3059])and Tqd.id.Value or nil,v=0}
Uqd.v=math.max(Uqd.v,Sqd.Value)
bb.helperDealt[Pqd]=Uqd
end
end
end
function bb.watchHelpers()
local Vqd=workspace:FindFirstChild(rcf[5016])
if not Vqd then
return
end
table.insert(F.conns,Vqd.ChildAdded:Connect(function(Wqd)
task.spawn(function()
local Xqd=Wqd:WaitForChild(rcf[2736],3)
task.wait(0.1)
local Yqd=Xqd and Xqd:FindFirstChild(rcf[5019])
local Zqd=Xqd and Xqd:FindFirstChild(rcf[3060])
if not(Zqd and Yqd and Yqd.Value)then
