end
local function erd()
local frd=bb.helperDealt[Wqd]or{id=Xqd.id.Value,owner=ard,v=0}
frd.v=math.max(frd.v,Zqd.Value)
bb.helperDealt[Wqd]=frd
end
erd()
table.insert(F.conns,Zqd.Changed:Connect(erd))
end)
end))
end
bb.ATK_KEEP,bb.ATK_NEED=60,5
bb.ATK_SKIP={fx=true,effects=true,initial_fx=true,move_back=true,move_to_range=true,end_fx=true,sounds=true,sound=true,animation=true}
function bb.atkPlain(grd,hrd)
hrd=hrd or 0
local ird=type(grd)
if ird==rcf[2665]then
return(grd==grd and grd~=math.huge and grd~= -math.huge)and grd or nil
end
if ird==rcf[1566]or ird==rcf[2666]then
return grd
end
if ird~=rcf[2664]or hrd>8 then
return nil
end
local jrd={}
for krd,lrd in pairs(grd)do
if(type(krd)==rcf[1566]or type(krd)==rcf[2665])and not bb.ATK_SKIP[krd]then
jrd[krd]=bb.atkPlain(lrd,hrd+1)
end
end
return jrd
end
function bb.atkSame(mrd,nrd)
if type(mrd)~=type(nrd)then
return false
end
if type(mrd)~=rcf[2664]then
return mrd==nrd
end
for ord,prd in pairs(mrd)do
if not bb.atkSame(prd,nrd[ord])then
return false
end
end
for qrd in pairs(nrd)do
if mrd[qrd]==nil then
return false
end
end
return true
end
function bb.atkKeep()
P.atkData=type(P.atkData)==rcf[2664]and P.atkData or{}
local rrd={}
for srd,trd in ipairs(bb.team or{})do
local urd=trd.id and V.rows(trd.id)
local vrd={}
for wrd=0,urd and urd.max or-1 do
local xrd=urd[wrd]
if xrd then
if xrd.atk then
vrd[xrd.atk]=true
end
if xrd.active then
vrd[xrd.active]=true
end
for yrd,zrd in pairs(type(xrd.sec)==rcf[2664]and xrd.sec or{})do
if type(zrd)==rcf[1566]then
vrd[zrd]=true
elseif type(zrd)==rcf[2664]and type(zrd.id)==rcf[1566]then
vrd[zrd.id]=true
end
end
end
end
for Ard in pairs(vrd)do
local Brd=N.Attacks[Ard]
if type(Brd)==rcf[2664]and type(Brd.aoe)==rcf[2664]then
local Crd=bb.atkPlain(Brd)
if not bb.atkSame(Crd,P.atkData[Ard])then
if P.atkData[Ard]==nil and not V._fill[Ard]and not N.FILL_ATTACKS[Ard]and not V.fillAlias(Ard)then
table.insert(rrd,V.name(trd.id)..rcf[5277]..Ard)
end
P.atkData[Ard]=Crd
V._atk={}
end
end
end
end
if#rrd>0 then
table.sort(rrd)
F.log(1,rcf[3055],rcf[5278]..table.concat(rrd,rcf[2788]))
end
F.saveSoon()
end
function bb.atkNote(Drd,Erd,Frd)
P.atkSeen=type(P.atkSeen)==rcf[2664]and P.atkSeen or{}
local Grd=P.atkSeen[Drd]
if type(Grd)~=rcf[2664]or type(Grd.h)~=rcf[2664]then
Grd={id=Erd,n=0,h={},c={},sp={},rc=0,k=0}
P.atkSeen[Drd]=Grd
end
Grd.c,Grd.sp=type(Grd.c)==rcf[2664]and Grd.c or{},type(Grd.sp)==rcf[2664]and Grd.sp or{}
Grd.id,Grd.n,Grd.at=Erd,(tonumber(Grd.n)or 0)+1,os.time()
table.insert(Grd.h,Frd.hit)
table.insert(Grd.c,Frd.crowd)
table.insert(Grd.sp,math.floor(Frd.spread*10+0.5)/10)
while#Grd.h>bb.ATK_KEEP do
table.remove(Grd.h,1)
table.remove(Grd.c,1)
table.remove(Grd.sp,1)
end
Grd.rc=math.max(tonumber(Grd.rc)or 0,math.floor(Frd.reach*100+0.5)/100)
Grd.k=math.max(tonumber(Grd.k)or 0,Frd.strikes)
F.saveSoon()
local Hrd=V.atkSeen(Drd)
if Hrd and(not Grd.said or(Hrd.sure and Grd.said~=rcf[5279]))then
Grd.said=Hrd.sure and rcf[5279]or rcf[5089]
