function bb.atkRead(Ird,Jrd)
local Krd,Lrd=Ird.t0-0.12,Ird.last+0.12
local Mrd,Nrd={},0
for Ord,Prd in ipairs(Jrd)do
if Prd.t>=Krd and Prd.t<=Lrd then
for Qrd in pairs(Prd.changed)do
if Qrd~=Ird.m then
return nil,rcf[5287]
end
end
for Rrd,Srd in ipairs(Prd.drops)do
local Trd=Mrd[Srd.m]or{n=0,pos=Srd.pos}
