local Urd={}
for Vrd,Wrd in pairs(Mrd)do
table.insert(Urd,Wrd)
end
if#Urd==0 then
return nil,rcf[5288]
end
if Nrd>Ird.dealt*1.25+1 then
return nil,rcf[5289]
