Zrd=math.max(Zrd,asd.n)
Yrd=math.max(Yrd,((asd.pos.X-Ird.pos.X)^2+(asd.pos.Z-Ird.pos.Z)^2)^0.5/math.max(1,Ird.range))
for bsd=_rd+1,#Urd do
Xrd=math.max(Xrd,((asd.pos.X-Urd[bsd].pos.X)^2+(asd.pos.Z-Urd[bsd].pos.Z)^2)^0.5)
end
end
return{hit= #Urd,crowd=math.max(Ird.crowd,#Urd),spread=Xrd,reach=Yrd,strikes=Zrd}
end
