Psd={m=Nsd.m,id=Nsd.id,atk=Nsd.atk,range=Nsd.range,cd=Nsd.cd,pos=Qsd,crowd=Rsd,t0=lsd,dealt=0}
gsd[Nsd.m]=Psd
