bb.REAL_WIN=75
function bb.realK(Otd)
local Ptd=bb.realC
local Qtd=U.now()
if not Ptd then
Ptd={t=0,k={},snaps={},seen={}}
bb.realC=Ptd
end
if Qtd-Ptd.t>=5 then
Ptd.t=Qtd
Ptd.k={}
local Rtd,Std,Ttd=pcall(bb.damageShares)
local Utd={}
if Rtd and type(Std)==rcf[2664]and(Ttd or 0)>0 then
for Vtd,Wtd in pairs(Std)do
Utd[Vtd]=Wtd*Ttd
end
end
local Xtd,Ytd={},0
for Ztd,_td in ipairs(bb.mine or{})do
local aud=_td:FindFirstChild(rcf[2736])
local bud=aud and aud:FindFirstChild(rcf[3059])and aud.id.Value
if bud and not V.isFarm(bud)then
local cud,dud=pcall(bb.liveDps,_td,bud)
dud=cud and tonumber(dud)or 0
Xtd[bud]=(Xtd[bud]or 0)+dud
Ytd=Ytd+dud
Ptd.seen[bud]=Ptd.seen[bud]or Qtd
end
end
table.insert(Ptd.snaps,{t=Qtd,abs=Utd})
while#Ptd.snaps>1 and Qtd-Ptd.snaps[2].t>=bb.REAL_WIN do
table.remove(Ptd.snaps,1)
end
local eud=Ptd.snaps[1]
if Qtd-eud.t>=20 and Ytd>0 then
local fud,gud={},0
for hud in pairs(Xtd)do
local iud=math.max(0,(Utd[hud]or 0)-(eud.abs[hud]or 0))
fud[hud]=iud
gud=gud+iud
end
if gud>0 then
local jud
for kud,lud in pairs(Xtd)do
if Qtd-Ptd.seen[kud]>=eb.REAL_AGE then
local mud=eb.realK(fud[kud]/gud,lud/Ytd,eb.REAL_AGE)
if not jud or mud<jud then
jud=mud
end
end
end
for nud,oud in pairs(Xtd)do
Ptd.k[nud]=eb.realK(fud[nud]/gud,oud/Ytd,Qtd-Ptd.seen[nud],jud)
end
end
end
end
return Ptd.k[Otd]or 1
end
function bb.upPath(pud,qud,rud,sud,tud,uud,vud,wud)
