oMd=1e6+mb.cardPearls(fMd,VLd)*10+lMd+nMd
elseif ZLd==rcf[3263]then
oMd=nMd*1e6+lMd
end
if not aMd or oMd>aMd then
_Ld,aMd,bMd,cMd=eMd,oMd,gMd,lMd
end
table.insert(dMd,string.format(rcf[5462],tostring(eMd),tostring(type(fMd)==rcf[2664]and fMd.title or rcf[2917]),(type(fMd)==rcf[2664]and fMd.weather)and(rcf[3418]..tostring(fMd.weather)..rcf[3204])or rcf[1580],tostring(type(fMd)==rcf[2664]and fMd.option_type or rcf[2917]),gMd,math.floor(lMd+0.5),table.concat(hMd,rcf[3333])))
