local cNd={string.format(rcf[5485],bb.HUNT_WEAK_RUNS,aNd,bNd)}
local dNd
for eNd,fNd in ipairs(W.lastScored or{})do
if fNd.kind~=rcf[2687]and(tonumber(fNd.score)or 0)>0 then
dNd=fNd
