function bb.rogueEffect(aOd)
local bOd,cOd,dOd=aOd.type,tonumber(aOd.amount)or 0,tostring(aOd.stat or rcf[1580])
if bOd==rcf[3245]then
return 1,math.abs(cOd)
end
if bOd==rcf[4811]or bOd==rcf[4816]or bOd==rcf[4812]then
if dOd==rcf[3116]then
return math.max(0.3,1+cOd),0
end
if dOd==rcf[2934]then
return math.max(0.5,1+cOd/2),0
end
if dOd:find(rcf[3501])then
return 1/math.max(0.3,1+cOd),0
end
return 1,0
end
if bOd==rcf[5492]then
if dOd==rcf[3116]then
return math.max(0.3,cOd),0
end
if dOd==rcf[2934]then
return math.max(0.5,1+(cOd-1)/2),0
end
if dOd:find(rcf[3501])then
