end
if bOd==rcf[4824]then
return 1/math.max(0.3,1+cOd),0
end
if bOd==rcf[5493]then
return math.max(0.2,1-bb.rogueShare(aOd.damage_type)*(1-100/(100+cOd))),0
end
if bOd==rcf[5494]then
return 1+bb.rogueShare(aOd.damage_type)*cOd,0
end
if bOd==rcf[5495]then
return math.max(0.5,1-cOd*0.5),0
end
if bOd==rcf[5496]then
return math.max(0.5,1-cOd*0.2),0
end
if bOd==rcf[5497]then
return 1+cOd*0.1,0
end
if bOd==rcf[5498]then
return 1/math.max(0.3,1+cOd*0.5),0
end
if bOd==rcf[5499]then
return math.max(0.5,1-cOd*0.1),0
end
if bOd==rcf[4819]then
return 1/math.max(0.3,1+cOd),0
end
if bOd==rcf[4825]then
return math.max(0.3,1-cOd*20),0
end
if bOd==rcf[4826]then
return math.max(0.5,1-cOd*0.03),0
end
if bOd==rcf[5500]then
return 0.95,0
end
if bOd==rcf[4827]then
return math.max(0.5,1-cOd),0
end
if bOd==rcf[5501]then
return 1+math.min(0.3,cOd/40000),0
end
if bOd==rcf[4820]then
return 1/math.max(0.3,1+cOd/2),0
end
if bOd==rcf[5502]then
return 0.8,0
end
if bOd==rcf[5503]then
local eOd=math.max(1,math.abs(cOd))*math.max(1,math.abs(tonumber(aOd.tier)or 1))
