function bb.learn()
local gOd=bb.calRun and bb.calRun.potBy
if type(gOd)~=rcf[2664]then
return
end
pcall(bb.sampleHelpers,true)
local hOd={}
for iOd,jOd in pairs(bb.ownDealt or{})do
if not V.isFarm(jOd.id)then
hOd[jOd.id]=(hOd[jOd.id]or 0)+(tonumber(jOd.v)or 0)
end
end
for kOd,lOd in pairs(bb.helperDealt or{})do
if lOd.owner and V.SUMMONER[lOd.owner]and not V.droneHelper(lOd)then
hOd[lOd.owner]=(hOd[lOd.owner]or 0)+(tonumber(lOd.v)or 0)
end
end
local mOd=type(bb.calRun.potExp)==rcf[2664]and bb.calRun.potExp or{}
local nOd,oOd=0,0
local pOd={}
for qOd,rOd in pairs(gOd)do
if rOd>0 then
nOd,oOd=nOd+(hOd[qOd]or 0),oOd+rOd
local sOd=tonumber(mOd[qOd])or rOd
if sOd>0 then
table.insert(pOd,{id=qOd,r=(hOd[qOd]or 0)/sOd,w=sOd})
end
end
end
if nOd<=0 or oOd<=0 then
return
end
table.sort(pOd,function(tOd,uOd)
return tOd.r<uOd.r
end)
local function vOd(wOd)
local xOd,yOd=0,0
for zOd,AOd in ipairs(pOd)do
if AOd.id~=wOd then
xOd=xOd+AOd.w
end
end
if xOd<=0 then
return nil
end
for BOd,COd in ipairs(pOd)do
if COd.id~=wOd then
yOd=yOd+COd.w
if yOd>=xOd/2 then
return COd.r
end
end
end
end
bb.lastEff={}
for DOd,EOd in pairs(gOd)do
local FOd=vOd(DOd)
if EOd>0 and EOd/oOd>0.02 and FOd and FOd>0 then
local GOd=P.learn[DOd]or{eff=1,n=0,v=6}
V.learnUp(DOd,GOd)
local HOd=math.max(0.02,0.25*math.sqrt(30/(30+GOd.n)))
local IOd=U.clamp(((hOd[DOd]or 0)/EOd)/FOd,0.2,6)
bb.lastEff[DOd]=math.floor(IOd*1000+0.5)/1000
GOd.eff=GOd.eff+(IOd-GOd.eff)*HOd
GOd.n=GOd.n+1
P.learn[DOd]=GOd
end
end
local JOd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if JOd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==rcf[2664]and P.mapLearn or{}
local KOd=type(P.mapLearn[JOd])==rcf[2664]and P.mapLearn[JOd]or{}
for LOd,MOd in pairs(bb.lastEff)do
local NOd=type(KOd[LOd])==rcf[2664]and KOd[LOd]or{eff=MOd,n=0,v=6}
if(tonumber(NOd.v)or 0)<4 then
NOd.eff,NOd.v=(tonumber(NOd.eff)or MOd)*V.secRescale(LOd),4
end
if(tonumber(NOd.v)or 0)<5 then
NOd.eff,NOd.v=(tonumber(NOd.eff)or MOd)*(V.sumRescale(LOd)or 1),5
end
if(tonumber(NOd.v)or 0)<6 then
NOd.eff,NOd.v=(tonumber(NOd.eff)or MOd)*(1-(V.SUMMONER[LOd]and V.SUMMONER[LOd].droneShare or 0)),6
end
local OOd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(NOd.n)or 0))))
NOd.eff=(tonumber(NOd.n)or 0)==0 and MOd or((tonumber(NOd.eff)or MOd)+(MOd-(tonumber(NOd.eff)or MOd))*OOd)
NOd.n=(tonumber(NOd.n)or 0)+1
KOd[LOd]=NOd
end
KOd._at=os.time()
P.mapLearn[JOd]=KOd
if U.count(P.mapLearn)>80 then
local POd,QOd
for ROd,SOd in pairs(P.mapLearn)do
if not QOd or(tonumber(SOd._at)or 0)<QOd then
POd,QOd=ROd,tonumber(SOd._at)or 0
end
end
P.mapLearn[POd]=nil
end
end
end
function bb.randomTeam()
