local pVd=((tonumber(mVd.base)or 0)-(tonumber(nVd.base)or 0))/oVd
if pVd<=0 or(tonumber(nVd.base)or 0)<=0 then
return false
end
local qVd=nVd.base/pVd
local rVd,sVd=0,0
local tVd,uVd=mVd.foes or{},nVd.foes or{}
for vVd,wVd in pairs(uVd)do
if wVd.prog>=bb.BASE_END then
rVd=rVd+wVd.hp
local xVd=tVd[vVd]
if xVd then
sVd=sVd+math.max(0,xVd.hp-wVd.hp)
end
end
end
for yVd,zVd in pairs(tVd)do
if zVd.prog>=bb.BASE_END and not uVd[yVd]then
sVd=sVd+zVd.hp
end
end
if rVd<=0 then
return false
end
local AVd=sVd/oVd
local BVd=AVd>0 and rVd/AVd or math.huge
local CVd={baseTime=qVd,loss=pVd,atEnd=rVd,rate=AVd,killTime=BVd}
return qVd<bb.BASE_SOON and BVd>qVd*bb.BASE_MARGIN,CVd
end
